programs.sol:
"""Recognize a small mixture of recurring textual formulas.

The strongest negative responses complete English 'in ...' expressions.
Positive responses mark notebook prompts, numeric references, SQL existence
checks and a few status/worksheet formulas. Coefficients are approximate
training averages, not a claim that all these uses have one meaning.
Small document-start adjustments cover articles, imports and escapes.
Only a short text suffix is kept; it resets at document boundaries.
"""
import re

READS = ()

# Conventional complements of the preposition "in".
IN_IDIOMS = {
    'relation': -5.5,
    'respect': -5.3,
    'regard': -3.3,
    'regards': -3.2,
    'connection': -2.2,
    'turn': -1.65,
    'view': -1.35,
    'return': -1.25,
    'exchange': -0.95,
    'effect': -0.9,
    'reality': -0.85,
    'advance': -0.75,
    'practice': -1.0,
    'conjunction': -0.55,
    'theory': -0.6,
    'light': -0.3,
    'mind': -0.3,
    'general': -0.23,
    'front': 0.27,
    'motion': -1.5,
    'existence': -1.8,
    'relationship': -2.5,
}


INTO_IDIOMS = {
    'play': -2.5,
    'account': -0.7,
    'consideration': -0.38,
}


def predict(token, previous, tail, first):
    word = token.strip().lower()
    before = previous.strip().lower()
    value = 0.0
    if token.startswith(' ') and before == 'in':
        value = IN_IDIOMS.get(word, 0.02)
        if previous.strip() == 'In' and word == 'practice':
            value = -2.5
    if token.startswith(' ') and before == 'into':
        value = INTO_IDIOMS.get(word, 0.0)
    if word == 'to' and before == 'relation':
        if re.search(r'\bin relation to$', tail, re.I):
            value = -1.75
    if token == ' exit' and before == 'with':
        value = 1.18
    if token in (' entry', ' exit') and previous.strip() == 'On':
        value = 8.0 if word == 'entry' else 6.3
    if token == ' EXISTS':
        if previous.strip() == 'IF':
            value = 7.2
        elif previous.strip() == 'NOT':
            value = 2.0
    if token == ' exists' and re.search(
            r'\btable if (?:not )?exists$', tail, re.I):
        value = 4.0 if before == 'not' else 6.0
    if token == ' already':
        if before in ('not', "'t", '’t', 'never'):
            value = 1.4
        elif before == 'requirement':
            value = 2.1
    if word == 'worksheets':
        value = -0.25
        if re.search(r'\bof the worksheets$', tail, re.I):
            value = 15.0
        elif re.search(r'\btop \d+ worksheets$', tail, re.I):
            value = 10.5
        elif before == 'this':
            value = 5.0
    if token.startswith(' plagiar') and before == 'use':
        value = 7.0
    if word == 'now' and tail.lower().endswith('referring now'):
        value = 0.8
    if word == 'head' and before == 'running':
        value = 1.6

    # Notebook input/output prompts have distinct opening and closing marks.
    if token == '\xa0' and previous == 'In':
        value = 6.0
    if token.strip() == '[':
        if re.search(r'\bIn\xa0\[$', tail):
            value = 6.5
        elif previous.strip() == 'Out':
            value = 6.5
        elif previous.strip() == 'In':
            value = 4.5 if token == '[' else 1.8
    if token.startswith(']:'):
        m = re.search(r'\b(In|Out)([ \xa0]*)\[[\d \xa0]*\]:\s*$', tail)
        if m:
            value = 4.8 if m[1] == 'Out' else (8.5 if m[2] else 3.2)
        elif re.search(r'(?:^|\n)\[\d+\]:\s*$', tail):
            value = 2.5
    if token == ']':
        m = re.search(r'(^|[\s.])\[(\d{1,6})\]$', tail)
        if m:
            left = tail[:m.start()] + m[1]
            value = 0.7
            if m[2].startswith('00'):
                value = 0.4
            elif left.rstrip().endswith('.'):
                value = 2.5
            elif '\n' in left[-5:]:
                value = 1.4
        elif previous.strip() == 'INFO':
            value = 0.72
    if token == ':' and previous.strip() == 'In':
        value = 2.0
    if token == ':' and re.search(r'/\*\s+By:$', tail):
        value = 2.7
    if tail == 'Title:':
        value = -2.65
    if first:
        if word == 'the':
            value = -0.55 if token == 'The' else -0.4
        elif token == 'package':
            value = -0.84
        elif token == 'import':
            value = 0.67
        elif token.strip() == '\\':
            value = 1.4
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    tail = (tail + token)[-100:]
    value = predict(token, previous, tail, first)
    return (doc, token, tail), float(value)

"""Approximate the contrast between decimal points and list-item punctuation.

Points after digits are negative, except that small line-initial numbers
usually make them positive. Number size and the preceding character adjust
this response: zero, year-sized numbers, version prefixes, and dotted-number
continuations have distinct strengths. Line-initial bullets and closing
list-label delimiters are positive; most other tokens are inactive.

Only a 300-character suffix is retained, reset at each document boundary.
Both actual newlines and written-out backslash-n separators count as lines.
This deliberately leaves other token-specific variation unexplained.
"""
import math
import regex as re

READS = ()
LABEL = r'(?:\(?[0-9一二三四五六七八九十]+|[A-Za-z]|[IVXivx]+)'


def number_point(before):
    match = re.search(r'([0-9]+)$', before)
    if not match:
        return None
    digits = match[0]
    n = int(digits[-8:])
    magnitude = min(4.0, math.log10(n + 1))
    lead = before[:match.start()]
    ch = lead[-1:]
    value = -1.2 - 0.7 * (n == 0) - 0.35 * (n == 1)
    value += 0.05 * magnitude + 0.65 * (len(digits) == 4)
    if ch == '.':
        value += 0.85 + 0.25 * (n == 0) - 0.25 * magnitude
    elif ch and ch.isascii() and ch.isalpha():
        value += 0.3 + 0.2 * ch.isupper()
        if ch in 'vV':  # a version prefix
            value -= 1.1
    elif ch == '_':
        value -= 0.4
    elif ch and ch in '($~≈':
        value -= 0.45
    elif ch and ch in '=:+*/^':
        value += 0.3
    elif ch and re.match(r'\p{Script=Han}', ch):
        value -= 1.4

    real_line = lead.rsplit('\n', 1)[-1].strip(' \t\r#>')
    logical_line = re.split(r'\n|\\n', lead)[-1].strip(' \t\r#>')
    if not logical_line:
        value += 2.85 if not real_line else 1.9
        value -= 2.0 * (n == 0) + 0.25 * (n == 1)
        value -= 0.85 * magnitude
        if not lead.strip(' \t#>'):
            value -= 0.5
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    line = re.split(r'\n|\\n', before)[-1].strip(' \t\r#>')
    label = bool(re.fullmatch(LABEL, line))
    value = 0.0
    if token == '.':
        numeric = number_point(before)
        if numeric is not None:
            value = numeric
        elif label:
            value = 0.7
        if not before:
            value = 0.24
    elif token in ('-', ' -'):
        if not line:
            value = 0.6 if token == '-' else 0.85
        else:
            value = -0.03
    elif token in ('*', ' *'):
        if not line:
            value = 0.3 if token == '*' else 0.06
    elif token in (')', '、', '．') and label:
        value = 0.7
    elif token == '•':
        value = 0.15 if not line else 0.0
    elif token == ' .':
        value = -0.08
    return (doc, (before + token)[-300:]), float(value)

"""Local z/i spelling fragments, with a few separate formatting corrections.

The positive spelling response is strongest for short zi pieces and for io
immediately after z. Nearby letters, capitalization of the current word, and
Cyrillic/Arabic spellings modify its size. Most other tokens predict near zero.
Negative corrections cover document starts and some split Unicode characters;
forum navigation labels and middle-dot dividers have their own small rules.
These rules approximate, rather than reproduce, the rare token interactions.
"""
from functools import lru_cache
import regex
from anyascii import anyascii

READS = ()
LETTERS = r'[\p{Latin}\p{Cyrillic}\p{Arabic}]+'

@lru_cache(maxsize=32768)
def spelling(b):
    text = b.decode('utf8', 'replace')
    whole = regex.fullmatch(LETTERS, text.strip())
    roman = anyascii(text.strip()).lower() if whole else ''
    ending = regex.search(LETTERS + '$', text)
    tail = anyascii(ending[0]).lower() if ending else ''
    return text, roman, tail


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pb, initial = b'', ''
    else:
        _, pb, initial = carry
    b = prefix.token_bytes[-1]
    s, c, _ = spelling(b)
    ps, _, previous = spelling(pb)
    space = bool(s and s[0].isspace())
    capitalized = initial.isupper()
    value = 0.0

    if not pb or pb == b'<|endoftext|>':
        value -= 0.174
        value += 0.067 * space
        value -= 0.033 * bool(c)
        value -= 0.079 * s[:1].isupper()
        value += 0.057 * (len(s.strip()) <= 2)

    if c and len(c) <= 4 and 'zi' in c:
        if space:
            value += 0.087
        else:
            value += {2: 1.57, 3: 0.31, 4: -0.26}.get(len(c), 0)
            if len(c) >= 3 and c[-1] in 'aeiou':
                value += 0.64
            if c.endswith('zio'):
                value += 0.80
            value += 0.69 * capitalized
            value -= 0.69 * previous.endswith('d')
            value += 1.70 * previous.endswith('t')
    if c and not space and len(c) <= 3 and 'zo' in c:
        value += 0.19
    if c == 'io' and not space:
        value += 0.05 + 0.34 * s.isupper()

    if previous.endswith('z') and c and not space:
        if c.startswith('i'):
            value += 0.21 + 0.37 * capitalized
            value += 0.48 * (len(c) == 1)
            value -= 0.41 * (len(c) >= 4)
            if c == 'io':
                value += 4.01
            elif c.startswith('io'):
                value += 0.60
            if c.startswith('ia'):
                value += 0.43
            if c.startswith('ie'):
                value += 1.12
            if c.startswith('iu'):
                value += 1.86
            if s.startswith('і'):
                value += 1.80  # Ukrainian dotted i, unlike Cyrillic и.
        if c == 'es':
            value += 0.92
        if c.startswith('zi'):
            value += 1.17
        if s in ('ی', 'ي', 'ى'):
            value += 0.40  # Arabic/Persian yeh.
        if s == 'ё':
            value += 1.44  # Cyrillic yo.

    if b and all(128 <= x < 192 for x in b):
        value -= 0.05
        # U+1F00--U+1FFF: an unfinished Greek Extended character after a space.
        if pb == b' \xe1' and b[0] >= 0xbc:
            value -= 5.25
        if pb.startswith(b'\xee') or pb.startswith(b' \xee'):
            value -= 0.39  # Fragments in the Unicode private-use area.
    if s.strip() == 'permalink' or (s.strip() == 'Tags' and ps.strip() == 'Show'):
        value += 0.89
    if len(s) >= 2 and set(s) == {'·'}:
        value -= 0.92

    # Only the first character of the current word is needed for capitalization.
    ending = regex.search(r'[\p{L}\p{N}]+$', initial + s)
    initial = ending[0][:1] if ending else ''
    return (doc, b, initial), float(value)

"""Sparse approximation of the large responses, not the diffuse background.

Negative: tip/tick spellings, split-token completions, and Chinese expressions
for hints, pointed ends, or techniques. Positive: repeated printed tab escapes.
Greek tau followed by eta/iota is negative; epsilon is positive, with a short
spillover onto the next consonant. A document-initial Title: header is another
positive case. State is local to one document.
"""
import re
import string

READS = ()

# The different senses of English "tip", expressed in Chinese.
CHINESE_TIPS = {
    '提示': -3.5,       # hint / prompt
    '温馨提示': -3.5,   # friendly reminder
    '尖': -5.3,         # pointed end
    '舌尖': -2.2,       # tip of the tongue
    '技巧': -1.0,       # technique
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0, 0.0)
    _, previous, position, tabs, greek = carry
    token = prefix.token_strings[-1]
    word = token.strip(string.whitespace + string.punctuation)
    lower = word.lower()
    value = 0.0
    next_greek = 0.0

    if token == r'\t':
        value = 0.05
        if tabs:
            value = 3.3 if tabs == 1 else 4.0 if tabs == 2 else 3.8
        if position == 0:
            value = 5.01
        elif not tabs and previous.endswith('t'):
            value = 3.3
    elif position == 1 and previous == 'Title' and token == ':':
        value = 8.56
    elif re.fullmatch(r'tip(?:s|p(?:ing|ed|er|ers))?', lower):
        value = -3.8 if lower == 'tips' else -6.0
        if lower == 'tips' and token.startswith(' ') and word[0].isupper():
            value = -4.8
        if lower == 'tipping':
            value = -6.7
        if lower == 'tip' and not token.startswith(' ') and word.islower():
            value = -9.0
    elif lower.removesuffix('s') in ('fingertip', 'wingtip', 'tooltip'):
        value = -3.2
    elif lower.removesuffix('s') == 'tick':
        value = -1.7 if token.startswith(' ') else -2.8
    elif token and token[0].isalpha() and previous.endswith(('t', 'T')):
        continuation = token.lower()
        stem = previous.strip(string.whitespace + string.punctuation)
        isolated_t = stem.lower() == 't'
        # ClientIP is a word join, unlike T + IP.
        camel_boundary = (token[0].isupper() and previous[-1].islower()
                          and not isolated_t)
        if not camel_boundary and re.fullmatch(r'ip[ps]?', continuation):
            value = -8.0 if isolated_t else -6.5
            if previous.lower().endswith('ant') and continuation == 'ips':
                value = -1.0
        elif isolated_t and re.fullmatch(r'i(?:cks?|ct)', continuation):
            value = -4.0
    elif previous.strip().lower() == 'ti' and re.fullmatch(r'p(?:t|s)?', token):
        value = -5.0
    elif (previous.lower().endswith('tip')
          and re.fullmatch(r'p(?:s|ing|ed)', token)):
        value = -4.5
    elif token in CHINESE_TIPS:
        value = CHINESE_TIPS[token]

    if previous.strip().lower() == 'τ':
        start = previous.startswith(' ') or previous == 'Τ'
        if token == 'ι':
            next_greek = -5.1 if start else -1.7
        elif token == 'η':
            next_greek = -4.1 if start else -1.2
        elif token == 'ε':
            next_greek = 4.2 if start else 1.5
        elif token == 'έ':
            next_greek = 9.8 if start else 5.4
        elif token == 'ύ':
            next_greek = 2.0
        value = next_greek
    elif greek and token and token[0].isalpha():
        if previous in ('ε', 'έ') and token[0] not in 'αεηιουωάέήίόύώ':
            value = greek * 0.4
        elif previous == 'ι' and token == 'ς':
            value = -3.3

    tabs = tabs + 1 if token == r'\t' else 0
    return (doc, token, position + 1, tabs, next_greek), value

"""A multilingual possessive-determiner signal, with a few context corrections.

Most possessives are negative. English responses strengthen after light verbs
and when a split word is completed; 'my' and 'our' strengthen in personal
narrative, while 'my' weakens in code. Recent function words distinguish
languages and the non-possessive uses of 'her', 'ma', etc. Contractions are
not treated as possessive apostrophes. Lowercase possessive-looking fragments
inside longer words instead get positive values, as does paired middle-dot
punctuation. At fresh starts, 'my', 'our' and 'your' also get positive values.
The program keeps 256 characters, resetting at document IDs and end markers.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
ENGLISH = {
    'my': -2.5, 'your': -1.75, 'his': -2.1, 'her': -1.85,
    'its': -2.1, 'our': -2.2, 'their': -2.3,
    'thy': -3.0, 'whose': -1.1,
}
FRENCH = set('mon ma ton ta son sa notre votre leur'.split())
FRENCH_PLURAL = set('mes tes ses nos vos leurs'.split())
SPANISH = {
    'mi': -2.8, 'mis': -2.6, 'tu': -4.2, 'tus': -3.0,
    'su': -4.8, 'sus': -3.1,
}
LANGUAGE_CUES = (
    set(('the of and to in is that for with on was are '
         'i you he she it we they').split()),
    set(('le les des du et une est ce cette pour dans avec ne '
         'je tu il elle nous vous').split()),
    set('el los las del al y una es se para por con lo no yo ella ellos usted'.split()),
    set('het een van voor niet om op dat deze als te met aan'.split()),
    set(('der die das den dem des und ist nicht ein eine einer '
         'mit von zu zum zur sich auch werden wird').split()),
    set(('il gli di della delle dello che non sono per come questo '
         'questa molto tutto tutti ma').split()),
)
CONTRACTION_HOSTS = set(
    'it he she that there here what who where how let'.split()
)

FRENCH_FORMS = FRENCH | FRENCH_PLURAL
AMBIGUOUS = FRENCH_FORMS | SPANISH.keys() | {'je', 'ons'}
LIGHT_VERBS = {'have', 'get', 'keep', 'make', 'take', 'put', 'do'}


@lru_cache(maxsize=512)
def verb_boost(word):
    roots = set(wordnet.base_forms(word))
    return 1.2 if 'have' in roots else 0.85 if roots & LIGHT_VERBS else 0.0


def language_scores(history):
    words = re.findall(r'[^\W\d_]+', history.lower())
    return [sum(w in cues for w in words) for cues in LANGUAGE_CUES]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    if text in {'<|endoftext|>', '<|im_end|>'}:
        return (doc, ''), 0.0
    word = text.strip().lower()
    previous = re.search(r'([^\W\d_]+)\Z', history)
    previous = previous.group(1) if previous else ''
    if history.endswith(('\\n', '\\r', '\\t')):
        previous = ''
    value = -0.003

    # Join split words, but do not mistake 'her' in a longer word for 'her'.
    inside = bool(text and text[0].isalpha() and previous)
    joined = (previous + text).lower() if inside else word
    if text == '··':
        value = 1.04
    elif joined in ENGLISH:
        value = ENGLISH[joined]
        narrative = bool(re.search(r'\b(I|me|we|us|said|felt|feel|love)\b',
                                   history[-200:]))
        code = (bool(re.search(r'[`{}=]|\\(?:frac|mathrm)', history[-200:]))
                or previous.lower() in {'def', 'class', 'function', 'import'})
        if joined == 'my':
            value = -2.8 if narrative else -1.9
            if code:
                value = -1.5 if text.strip().islower() else -0.9
                if not text[:1].isspace() and not inside:
                    value = -0.4 if text.islower() else -0.9
        elif joined == 'our' and narrative:
            value -= 0.55
        elif joined == 'her':
            en, *others = language_scores(history)
            if max(others) > en and max(others) >= 2:
                value = 1.1
            elif re.search(r'\bhim\s+(or|and)\s*\Z', history):
                value = 1.5
        if inside:
            value *= 2.0
        if not inside and joined != 'her':
            value -= verb_boost(previous.lower())
        if (previous + text if inside else text.strip())[:1].isupper():
            value *= 0.9 if joined != 'my' or narrative else 0.75
        if not text[:1].isspace() and not inside:
            value *= 0.85
    elif inside and word in ENGLISH:
        value = ({'my': 2.2, 'her': 1.6}.get(word, 0.6)
                 if text.islower() else 0.0)
    elif text in ("'s", '’s'):
        value = 0.0 if not previous or previous.lower() in CONTRACTION_HOSTS else -1.05
    elif text in ("'", '’') and previous.lower().endswith('s'):
        value = -0.7
    elif text == 's' and history.endswith(("'", '’')):
        value = -0.7
    else:
        foreign = joined if inside else word
        if foreign in AMBIGUOUS:
            en, fr, es, nl, de, it = language_scores(history)
            if foreign in FRENCH_FORMS and fr > en and fr >= max(es, nl, de, it):
                value = -4.0 if foreign in FRENCH else -2.7
                value = {'ma': -2.2, 'ta': -1.6}.get(foreign, value)
            elif foreign in SPANISH and es > en and es >= max(fr, nl, de, it):
                value = SPANISH[foreign]
            elif foreign in {'je', 'ons'} and nl > max(en, fr, es, de, it):
                value = -2.6
        if foreign in {'votre', 'notre', 'leur'}:
            value = -4.2
        elif foreign == 'leurs':
            value = -3.2
        elif foreign in {'nuestro', 'nuestra', 'nuestros', 'nuestras'}:
            value = -3.0
        elif foreign in {'suo', 'sua', 'suoi', 'seu', 'seus', 'suas'}:
            value = -1.7
        elif foreign in {'uw', 'mijn', 'onze'}:
            value = -3.2
        elif foreign in {'его', 'их'}:
            value = -1.8
        elif foreign in {'ее', 'её'}:
            value = -1.2
        elif re.fullmatch(r'(mein|dein|sein|ihr|unser|euer)(e|en|er|es|em)?', foreign):
            value = -1.0
        if value < -0.1 and text.strip().isupper():
            value = 0.0
        elif value < -0.1 and text.strip()[:1].isupper():
            value *= 0.8
    if not history and value < 0:
        value = 1.0 if word in {'my', 'our', 'your'} else 0.0
        if word == 'my' and text.strip().istitle():
            value = 3.5
    return (doc, (history + text)[-256:]), value

"""Respond to English question endings, particularly FAQ section headings.

Level-two Markdown questions are strongest. Smaller headings and unheaded
questions get a larger response after an earlier question section or an
explicit FAQ/related-questions label. Embedded question marks usually get a
small negative value. Other tokens are zero except for those section labels.
State resets between packed documents.
"""
import re

READS = ()
OPENING = re.compile(
    r"^(?:(?:What|How|Why|Which|Where|When|Who)(?: |['’]s )[a-z]"
    r"|(?:Is|Are|Do|Does|Can|Should|Will) [a-z])"
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        # FAQ state: 0 = ordinary text, 1 = question sections, 2 = explicit label.
        line, faq, questions = '', 0, []
    else:
        _, line, faq, questions = carry
    pos = prefix.position
    questions = [p for p in questions if pos - p < 150]
    token = prefix.token_strings[-1]
    joined = line + token
    value = 0.0
    caption = joined.strip().lstrip('#').strip().lower()
    if (caption in ('related questions', 'similar questions')
            or caption.startswith(('faq', 'frequently asked questions'))):
        faq = 2
        if 'question' in token.lower() or 'faq' in token.lower():
            value = 0.5
    if '?' in token:
        value = -0.15
        heading = re.match(r'^\s*(#{1,6})\s+', joined)
        depth = len(heading[1]) if heading else 0
        body = joined[heading.end():] if heading else joined.lstrip()
        body = re.sub(r'^-\s*\d*\s*', '', body)
