        active = False
    elif active:
        bracket = (bracket + s)[-100:]
    recent = (recent + s)[-200:]
    return (doc, double, paired, single, recent, bracket, active, s), value

programs.haiku:
"""Omission and insertion marks inside quotations (layers.1.mlp.down_proj:3469).

What it does: this component goes negative on the punctuation that marks words cut out of, or
inserted into, quoted prose:

  * an ellipsis, "…", "...", "....", "……", after a word (strongest inside a quotation),
  * a spaced square bracket that opens an editorial insertion after a word, as in
    "when asked [a month earlier]", and the closing ] of that bracket when it holds words,
  * a dot repeated as a spaced ellipsis, ". .", inside a quotation.

A bracket glued to the word before it ("team[are]") and citation brackets such as [4] or
[0012] (digits inside) do not count. Everything else predicts 0. "Inside a quotation" is
tracked by the parity of straight double quotes and the open/close state of curly quotes,
reset at each new document. The magnitudes are hand-set to each case's typical activation,
not fitted to a table of tokens.

Measured on training rows: about 0.14 variance explained. A per-token lookup table would reach
about 0.16 to 0.24; the table adds the long tail of other tokens, which no short rule captures.
"""

READS = ()

DIGITS = "0123456789"


def _ends_in_word(text):
    return text[-1:].isalpha()


def _has_letters(text):
    return any(ch.isalpha() for ch in text)


def _has_digits(text):
    return any(ch in DIGITS for ch in text)


def step(carry, prefix, upstream):
    # carry: (inside a quotation, position of the latest spaced '[', document id)
    if carry is None or prefix.document_ids[-1] != carry[2]:
        inside, opened = False, -100
    else:
        inside, opened = carry[0], carry[1]
    t = prefix.position
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if t > 0 else ""
    after_word = _ends_in_word(prev)

    value = 0.0
    if "…" in token or "..." in token:
        # ellipsis: strong after a word inside a quotation
        if after_word:
            value = -2.5 if inside else -0.5
        else:
            value = -0.3
    elif token in ("[", " ["):
        opened = t if token == " [" else -100
        if after_word and token == " [":
            value = -2.2 if inside else -0.35
    elif token in ("]", "],", "].") and 0 < t - opened <= 10:
        # closing an editorial bracket: counts only if it holds words, not digits
        content = "".join(prefix.token_strings[opened + 1 : t])
        if _has_letters(content) and not _has_digits(content):
            value = -2.0 if inside else -0.6
    elif token.strip() == "." and prev.strip() == ".":
        # spaced ellipsis ". ." or ". . ."
        value = -6.0 if inside else -0.5

    # quote state after this token
    if token.count('"') % 2 == 1:
        inside = not inside
    for ch in token:
        if ch == "“":
            inside = True
        elif ch == "”":
            inside = False
    return (inside, opened, prefix.document_ids[-1]), value

programs.sol:
"""Partial predictor for recurring d-related spelling patterns.

Combine the previous d-ending fragment with the current token, then score
possible dictionary senses and consonant-letter clusters. Bare d, longer
prefixes, and unsplit words have different strengths. Other rules recognize
eggs, Cyrillic д-continuations, Greek δε, 大変, and document-initial 12.
Use only the last two tokens; reset the document-position count at boundaries.
These are readable regularities, not a complete semantic account: many
lexically irregular activations remain unmodeled instead of being memorized.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
# Columns: bare d, longer d-ending prefix, whole token, space-led token.
SENSE_STRENGTH = {
    'do': (-0.85, -0.16, 0.0, 0.0),
    'food': (0.47, 0.0, 0.0, 0.0),
    'food_object': (2.3, 0.7, 0.64, 0.25),
    'shaped_object': (0.92, 0.37, 0.11, 0.07),
    'person_object': (0.45, 0.28, 0.1, 0.0),
}
# Letter groups: strengths following bare d and a longer d-ending prefix.
CLUSTERS = [
    (('sh', 'ch'), (0.47, 0.0)),
    (('sk', 'ck'), (0.27, 0.15)),
    (('nd',), (0.38, 0.09)),
]
# Cyrillic continuations after д: bare-letter and longer-prefix strengths.
CYRILLIC = {
    'вер': (2.39, 0.13),
    'вор': (1.13, 0.0),
    'уш': (1.4, 0.84),
    'ом': (1.03, 0.19),
    'ост': (-1.18, -0.75),
}

@lru_cache(maxsize=12000)
def sense_strength(word):
    cats = wordnet.categories(word)
    if 'do' in wordnet.base_forms(word):
        group = 'do'
    elif 'noun.food' in cats:
        group = 'food_object' if 'noun.artifact' in cats else 'food'
    elif 'noun.artifact' in cats and 'noun.shape' in cats:
        group = 'shaped_object'
    elif 'noun.artifact' in cats and 'noun.person' in cats:
        group = 'person_object'
    else:
        group = ''
    return SENSE_STRENGTH.get(group, (0.0, 0.0, 0.0, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = carry[1] + 1 if carry is not None and carry[0] == doc else 0
    same = (prefix.position > 0 and
            prefix.document_ids[-2] == doc)
    previous = prefix.token_strings[-2] if same else ''
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    value = 0.0
    if text.isascii() and text.isalpha():
        match = re.search(r'[dD]([A-Za-z]{0,3})$', previous)
        if match:
            bare = re.fullmatch(r'[^A-Za-z]*[dD]', previous) is not None
            column = 0 if bare else 1
            combined = 'd' + match[1].lower() + word
            value += sense_strength(combined)[column]
            for letters, strengths in CLUSTERS:
                if any(cluster in word for cluster in letters):
                    value += strengths[column]
    if word.startswith('d') and word.isascii() and word.isalpha():
        value += sense_strength(word)[3 if text[:1].isspace() else 2]
    if word in ('egg', 'eggs'):
        value += 0.58 if text[:1].isspace() else 0.21
    if previous.lower().endswith('eg') and text.lower() in ('g', 'gs'):
        value += 0.98
    if previous.endswith('大') and text == '変':
        value += -2.19
    if previous.lower().endswith('д'):
        column = 0 if previous.strip().lower() == 'д' else 1
        for stem, strengths in CYRILLIC.items():
            if text.lower().startswith(stem):
                value += strengths[column]
    if previous.lower().endswith('δ') and text == 'ε':
        value += -0.92
    if position == 1 and previous == '1' and text == '2':
        value += 1.54
    return (doc, position), value

