word frequency distinguish name pieces from ordinary prose. Longer surname-like pieces after a familiar
forename get the largest response. No individual surnames are memorized.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS: tuple[str, ...] = ()

