""".split())

HONORIFICS = set("mr mrs ms miss dr prof professor sir dame lord lady "
                 "senator governor president saint st".split())

@lru_cache(32768)
def english(word):
    return zipf_frequency(word.lower(), "en")

@lru_cache(32768)
def international(word):
    # Suppress ordinary words in several common Latin-alphabet languages.
    return max(english(word), *(zipf_frequency(word.lower(), lang)
               for lang in ("de", "fr", "es", "it", "pt", "nl")))

@lru_cache(32768)
def categories(word):
    return wordnet.categories(word)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if token.startswith("<|") and token.endswith("|>"):
        return (doc, "", ()), 0.0
    if carry is None or carry[0] != doc:
        carry = (doc, "", ())
    _, stem, history = carry
    continued = bool(stem and token and token[0].isalpha())
    word = stem if continued else ""
    previous = list(history)
    if stem and not continued:
        previous.append(stem)
    for part in re.findall(r"[^\W\d_]+|[\W\d_]", token):
        if part.isalpha():
            word += part
        else:
            if word:
                previous.append(word)
                word = ""
            # A sentence or line ends the name phrase. Periods after an
            # initial or title, as in "John R. Smith", do not end it.
            if part in "\n.!?;:":
                left_word = previous[-1] if previous else ""
                abbreviation = (len(left_word) == 1 and left_word.isupper())
                abbreviation |= left_word.lower() in HONORIFICS
                if part != "." or not abbreviation:
                    previous = []
    previous = previous[-4:]
    carry = (doc, word, tuple(previous))
    if not word:
        return carry, 0.0

    left = previous[-1] if previous else ""
    given = word.lower() in GIVEN_NAMES
    after_given = left.lower() in GIVEN_NAMES
    n = len(word)
    capital = word[0].isupper()

    if not capital:
        if given and n >= 5:
            value = 1.18
        elif after_given and continued and english(stem) > 2.125:
            value = 0.77
        else:
            value = 0.0
        return carry, value

    # Frequencies are on wordfreq's logarithmic (Zipf) scale.
    freq = english(word)
    common = international(word)
    cats = categories(word)
    ordinary = bool(cats - {"noun.person", "noun.location"})
    personal = (after_given or (len(left) == 1 and left.isupper())
                or left.lower() in HONORIFICS
                or any(w.lower() in GIVEN_NAMES for w in previous[-3:]))

    if after_given:
        if not continued and ordinary and "noun.person" not in cats:
            value = 0.10
        elif n <= 3:
            value = 1.45 if freq <= 3.375 else 0.65
        elif common > 4.625:
            value = 1.98 if "noun.person" in cats else 0.71
        else:
            value = 2.25
    elif not continued:
        if given:
            value = 0.46
        elif common <= 4.875:
            value = 0.42 if personal else 0.07
        else:
            value = 0.0
    elif personal:
        if word.isupper():
            value = 0.13
        elif ordinary:
            value = 0.36
        else:
            value = 1.50 if 5 <= n <= 9 else 0.72
    elif ordinary:
        value = 0.09
    elif freq <= 1.375:
        if n >= 10:
            value = 0.07
        else:
            value = 0.18 if english(left) <= 0.125 else 0.43
    elif n <= 3:
        value = 0.09
    elif n == 4:
        value = 0.47
    else:
        value = 0.92 if common <= 4.375 else 0.30
    return carry, value

"""Approximate a negative response to a document with no token variety yet.

The pulse starts at a document boundary and persists while every token is
identical to the first one. Its size is coarsely estimated from the first
token's form: code-statement starters and whitespace are especially negative;
wide East Asian characters and special markers are less negative. After the
first change of token, use a near-zero baseline. Ordinary lexical variation
is intentionally left unexplained.
"""
import unicodedata

READS = ()

# Common declaration, import, and block starters across programming languages.
CODE_STARTERS = {
    'class', 'def', 'int', 'const', 'package', 'import', 'using',
    'export', 'from', 'type', 'function', 'void', 'namespace',
    'struct', 'enum', 'var', 'let', 'public', 'private', 'static',
    'interface', 'with',
}


def initial_value(text):
    word = text.strip()
    if text.startswith('<|'):
        return -0.40
    if text == '\r':
        return -2.05
    if not word:
        return -0.54 if '\n' in text else -1.05
    if word in CODE_STARTERS and not text[0].isspace():
        return -2.0
    if '\ufffd' in text or any(
        unicodedata.east_asian_width(c) in ('W', 'F') for c in text
    ):
        return -0.38
    if word.isdecimal():
        return -0.59
    if word.isascii() and word.isalpha():
        if text[0].isspace() and (word.istitle() or word.isupper()):
            return -0.41
        if not text[0].isspace() and word.islower():
            return -0.77
    if len(word) > 1 and len(set(word)) == 1 and not word[0].isalnum():
        return -1.2
    return -0.65


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or document != carry[0]:
        value = initial_value(prefix.token_strings[-1])
        carry = (document, token, True, value)
    else:
        doc, first_token, uniform, value = carry
        carry = (doc, first_token, uniform and token == first_token, value)
    return carry, carry[3] if carry[2] else 0.002

programs.haiku:
"""layers.1.mlp.down_proj:3474 -- a "document-opening token" detector.

What it does: this component is almost silent everywhere except on the FIRST token of a
document (the first token of a row, or the first token after a document boundary, where
the model resets its attention and positions). There it writes a strongly negative value
whose size depends on what that opening token is:
  * programming / markup / symbol-decoration openers (`import`, `def`, `#include`, `{`,
    `#`, `****`, `----`, type names like `int` or `string`) are the most negative;
  * ordinary English-like or number openers sit in the middle;
  * CJK (Chinese/Japanese/Korean) characters are the least negative.
Every other position predicts 0. The value depends only on the token itself, because at the
first position of a document the model sees nothing else.
"""

import unicodedata

READS = ()

# Words that open code, markup or config files.
CODE_WORDS = set(
    """import def class package include int float double string struct static const return
    public private var function bool char long unsigned void new uint self print null let fn
    pub use mod extends extern typedef enum namespace template using select from where with
    insert update create table""".split()
)


def is_code_opener(text):
    """A code word, a comment or preprocessor marker, or a run of decorative symbols."""
    s = text.strip()
    if s.lower() in CODE_WORDS or s in CODE_WORDS:
        return True
    if s.startswith(("#", "//", "/*", "**", "--")):
        return True
    return len(s) >= 3 and all(not c.isalnum() and c != " " for c in s)


def is_cjk(text):
    s = text.strip()
    return len(s) > 0 and all(unicodedata.category(c) == "Lo" and ord(c) > 0x2E80 for c in s)


def opener_value(text):
    if is_code_opener(text):
        return -1.3
    if is_cjk(text):
        return -0.3
    if text.startswith(" "):
        return -0.5
    return -0.7


def step(carry, prefix, upstream):
    first = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not first:
        return None, 0.0
    return None, float(opener_value(prefix.token_strings[-1]))

programs.sol:
"""A document-opening pulse, scaled by the kind of opening token.

The pulse usually disappears once a different token has been read. Opening
brackets, newlines, articles and non-Latin initials tend to give positive
pulses; digits and space-prefixed English words tend to give negative ones.
The remaining lexical variation is approximated by case, length and word
frequency, not by a table of token identities. A title-field colon is a
separate, delayed opening pulse.
"""
import unicodedata
import math
import regex
from wordfreq import zipf_frequency

READS = ()
SUBJECT_PRONOUNS = frozenset('you he she it we they'.split())


def opening_value(s):
    t = s.strip()
    space = s.startswith(' ')
    if s.startswith('<|'):
        return 4.9 if s == '<|endoftext|>' else 2.2
    if s == '\x00':
        return 12.9
    if not t:
        if '\u00a0' in s:
            return 4.4
        if '\n' in s:
            return (3.8 if s == '\n' else 2.1) if not space else 1.2
        return 0.3 if len(s) == 1 else -0.9
    if '\ufffd' in s:
        return 4.6
    if t.isdigit():
        return -0.7 if t.isascii() else 1.6

    # Punctuation roles, rather than a vocabulary lookup.
    if len(t) == 1 and unicodedata.category(t) == 'Ps':
        if '\n' in s:
            return 1.5
        if space:
            return 3.3
        if t == '{':
            return 10.3
        return 5.9 if t == '[' else 7.8
    if t in ('"', '“', '‘', "'"):
        return (2.2 if space else 4.8) if t != "'" else (2.4 if space else 1.7)
    if t and all(c in '·•' for c in t):
        return 1.0 if len(t) == 1 else 2.0
    if t in ('**', '__'):
        return 11.2 if t == '**' else 6.1
    if t and set(t) == {'#'}:
        return 3.6 if len(t) == 1 else 0.0
    if t in ('.', '。'):
        return 0.2 if '\n' in s else (0.5 if space else 2.8)
    if t in (',', '，'):
        return 0.1 if space else 2.2
    if t in ('-', '*', '/', '|', '<', '>'):
        return (0.5 if space else 2.7)
    if t in ('#include', '#import'):
        return 2.4
    if not any(c.isalpha() for c in t):
        return 0.2

    # Scripts and case distinguish non-English document initials.
    if regex.search(r'\p{Script=Cyrillic}', t):
        return (2.0 if space else 5.9) if t[0].isupper() else (1.0 if space else 1.6)
    if regex.search(r'\p{Script=Arabic}', t):
        return 1.4 if space else 2.9
    if not t.isascii():
        return 0.5 if space else 1.6

    low = t.lower()
    if low == 'a':
        return -1.1 if space else -0.8
    if low == 'an':
        return (7.0 if space else 12.6) if t == 'An' else 5.0
    if low == 'the':
        return (2.0 if t == 'The' else 0.17) if space else 2.7
    if low in SUBJECT_PRONOUNS:
        return (0.8 if t.istitle() else -0.2) if space else 2.3
    if low == 'i':
        return -0.1 if space else 0.5
    frequency = max(2.0, min(7.5, zipf_frequency(t, 'en')))
    length = math.log(len(t))
    # Short fragments and very common sentence starters are more positive
    # than familiar, longer whole words. Leading spaces shift the scale.
    if space:
        return -0.1 - 0.38 * length + 0.105 * (frequency - 5.5)**2
    if len(t) == 1 or t.isupper():
        return 0.3
    if t.istitle():
        return 2.7 - 1.3 * length + 0.33 * (frequency - 5.45)**2
    return 0.7 - 0.4 * length - 0.03 * frequency + 0.026 * frequency**2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(text)
        return (doc, token, True, text, 0, value), value
    _, first, uniform, first_text, age, initial_value = carry
    age += 1
    uniform = uniform and token == first
    value = initial_value if uniform else 0.0
    if age == 1 and first_text == 'Title' and text == ':':
        value = 8.8
    return (doc, first, uniform, first_text, age, initial_value), value

"""Approximate a document-opening pulse and split indefinite compounds.

The opening pulse persists while the initial token repeats. Token shape and
word classes estimate its height: numerals and referring words are weak;
code, markup and non-whitespace controls are stronger. Away from that run,
only split compounds such as 'some' + 'body' get appreciable predictions.
Individual words' remaining amplitude differences are deliberately omitted.
"""
import inflect
import unicodedata
import regex

READS = ()
ARTICLES = {'a', 'an', 'the'}
QUESTIONS = {'who', 'what', 'which', 'where', 'when', 'why', 'how', 'whom', 'whose'}
REFERRING = {'this', 'that', 'these', 'those', 'here', 'there', 'it'}
QUANTITIES = {'some', 'many', 'much', 'few', 'several', 'most', 'enough'}
DECLARATIONS = set('''import from include using require package module export
class struct enum namespace interface def function const var let static public
private protected int char float double bool void'''.split())
_engine = inflect.engine()
NUMBER_WORDS = {_engine.number_to_words(i) for i in range(21)}
NUMBER_WORDS |= {_engine.number_to_words(i) for i in range(30, 100, 10)}
NUMBER_WORDS |= {_engine.number_to_words(_engine.ordinal(i)) for i in range(1, 21)}
COMPOUND_ENDINGS = {'one': 1.0, 'body': 1.4, 'thing': 1.6, 'where': 1.1}


def opening_value(s):
    w = s.strip()
    lower = w.lower()
    spaced = s.startswith(' ')
    if not s:
        return 0.0
    if w.isascii() and w.isdecimal():
        return -0.7
    if s.startswith('<|'):
        return 2.7
    if any(unicodedata.category(c) == 'Cc' and not c.isspace() for c in s):
        return 20.0
    if s.isspace():
        return 3.3 if '\n' in s or (len(s) == 1 and s != '\t') else 4.8
    if lower in REFERRING:
        return -0.3
    if lower in NUMBER_WORDS:
        return -0.8
    if lower in QUANTITIES:
        return 0.4
    if lower in QUESTIONS:
        return 2.5 - 2.2 * spaced
    if lower in ARTICLES:
        return 6.2 - 1.6 * spaced
    if lower in DECLARATIONS:
        return 7.8 - 4.0 * spaced
    if w.startswith('#'):
        return 9.5 - 2.0 * spaced
    if w.startswith('//') or w.startswith('/*'):
        return 9.3 if '\n' in s else 6.0
    if len(w) > 1 and len(set(w)) == 1 and not w[0].isalnum():
        return 7.5
    if w in ',，;；:：':
        return 2.2
    if w in '.。!?？！':
        return 2.7
    if unicodedata.category(w[0]) == 'Pe':
        return 2.7
    if w.startswith('-'):
        return 6.7
    if w.startswith('\\'):
