"""layers.1.mlp.down_proj:3477: a document-opening detector.

The component is silent everywhere except on the first token of each document (the token
right after <|endoftext|>, or the first token of a packed row). There its value depends
only on which token it is, because attention at that position sees only itself. So the
program scores that one token by a few word-class rules:

  * numbers and number words ("1", "2019", "Five", "ninth") -> about 0, the weakest;
  * symbols and separators ("[],", "##", "══", "--") -> above the baseline;
  * the articles "The" / "the" -> a little above baseline;
  * tokens that begin with a leading space (mid-sentence pieces) -> below baseline;
  * long tokens (5+ characters) -> below baseline.

Everything else is a baseline value. Positions inside a document are predicted as 0.
"""

import re

READS = ()

NUMBER_WORDS = set(
    "zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen "
    "fifteen sixteen seventeen eighteen nineteen twenty thirty forty fifty sixty seventy "
    "eighty ninety hundred thousand million first second third fourth fifth sixth seventh "
    "eighth ninth tenth".split()
)
BASELINE = 4.4


def is_number(text):
    word = text.strip().lower()
    return bool(re.fullmatch(r"[0-9.,%]+", word)) or word in NUMBER_WORDS


def is_symbol(text):
    stripped = text.strip()
    return stripped != "" and not any(c.isalnum() for c in stripped)


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    if t > 0 and docs[t] == docs[t - 1]:
        return carry, 0.0  # not a document's first token: silent
    text = prefix.token_strings[t]
    value = BASELINE
    if is_number(text):
        value -= 4.4
    if is_symbol(text):
        value += 1.6
    if text.strip().lower() == "the":
        value += 2.0
    if text.startswith(" "):
        value -= 1.7
    if len(text.strip()) >= 5:
        value -= 1.1
    return carry, float(value)

