    _words.number_to_words(n): n
    for n in (*range(1, 21), *range(30, 100, 10))
}
NUMBER_WORDS.update(hundred=100, thousand=1000, million=1000000)
TEXT_UNITS = {' words', ' word', ' Words', '-word', ' слов'}


def quantity(text):
    """Read coarse quantity and roundness from a trailing number expression."""
    text = re.sub(r'(?:\+|\bmore|\bplus)\s*$', '', text).rstrip(' -')
    m = re.search(r'(\d[\d,]*)([千萬万億亿]?)[多余餘]?\s*$', text)
    if m:
        digits = m[1].replace(',', '')
        n = float(digits[-15:])
        n *= {'': 1, '千': 1000, '万': 10000, '萬': 10000,
              '億': 100000000, '亿': 100000000}[m[2]]
        return n, digits.endswith('0')
    if re.search(r'[一二两三四五六七八九十][百千萬万]\s*$', text):
        return 100, True  # Chinese-written hundreds or more: large-count bin.
    m = re.search(r'([A-Za-z-]+)\s*$', text)
    if m and m[1].lower() in NUMBER_WORDS:
        n = NUMBER_WORDS[m[1].lower()]
        return n, n >= 10
    if m and '-' in m[1]:
        parts = m[1].lower().split('-')
        if all(p in NUMBER_WORDS for p in parts):
            return sum(NUMBER_WORDS[p] for p in parts), False
    return None, False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position = '', 0
    else:
        _, before, position = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    n, rounded = (quantity(before)
                  if token in TEXT_UNITS or s in {'字', '元', '米', 'metre', 'metres'}
                  else (None, False))
    value = 0.0

    if token in TEXT_UNITS:
        value = -0.08
        if n is not None:
            if n >= 100:
                value = 8.8
            elif n >= 40 and rounded:
                value = 7.8
            elif n >= 10:
                value = 2.8
        elif re.search(r'\bother\s*$', before, re.I):
            value = 0.85
        elif re.search(r'\bnumber of\s*$', before, re.I):
            value = 1.0
        elif re.search(r'\bkind\s*$', before, re.I):
            value = 0.4
        if re.search(r'(?:\+|\bmore|\bplus)\s*$', before):
            value *= 0.75
        if token == ' word' and re.search(
                r'\d(?:st|nd|rd|th)\s*$', before):
            value = 0.8
    elif s == '字':
        value = -0.15
        if n is not None and n >= 100:
            value = 9.2
        elif n is not None and n >= 10:
            value = 5.0
        elif before.endswith('多少'):
            value = 5.0
    elif s == '元' and n is not None:
        value = 1.1 if rounded and n >= 50 else 0.15
    elif s == '米' and n is not None:
        value = 1.4 if n >= 100 else 0.15
    elif token in (' metre', ' metres') and n is not None:
        value = 1.0 if rounded and n >= 100 else 0.15

    if position == 0 and token == '//\n':
        value = 8.38
    elif position == 1 and before == 'Title' and token == ':':
        value = -8.14
    elif token == '\r' and not before.strip('\r'):
        value = 3.46

    return (doc, (before + token)[-120:], position + 1), float(value)

"""A negative spelling-family response centered on perfect/perfection.

Complete tokens and attached f-e/fect word fragments have different amplitudes.
Transliteration makes the spelling rules apply across accents and scripts.
Remember only an alphabetic word tail, resetting it at document boundaries.
Two literal rules cover Chinese 'perfect' and repeated middle dots. We omit
most weaker word-specific responses and positive activations.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def response(s, before):
    word = s.strip()
    if 'imperfect' in word:
        return -7.7
    if 'perfection' in word:
        return -7.0
    if 'perfectly' in word:
        return -4.65
    if 'perfect' in word:
        return -6.4
    if re.search(r'(parfait|perfekt|perfett|perfeit)', word):
        return -6.0
    if word.startswith('feast'):
        return -7.5
    if word.startswith('forfeit'):
        return -5.4
    if word == 'forfe':
        return -3.1
    if word == 'flawless':
        return -4.2
    if re.fullmatch(r'defects?', word):
        return -3.15
    if word == 'prefect':
        return -5.1
    if word.startswith('defect'):
        return -1.0
    if word.startswith(('infect', 'affecti')):
        return -0.4
    if word == 'perf':
        return -1.5
    # Only joined spelling pieces, never the next space-prefixed word.
    if s and s[0].isalpha() and before:
        if before.endswith(('perfect', 'parfait')):
            return -4.5
        if before.endswith('fect') and not before.endswith(('effect', 'affect')):
            return -3.0
        if before.endswith(('par', 'for')) and s.startswith('fait'):
            return -9.0
        if before.endswith('par') and s == 'fa':
            return -6.5
        if before.endswith('pref') and s.startswith('ect'):
            return -15.0 if s == 'ect' else -7.0
        if before.endswith('conf') and s.startswith('ett'):
            return -9.5
        if re.search(r'(perf|parf|perfe|parfa)$', before):
            if re.match(r'(e[ck]|ett|ai|it)', s):
                return -9.5
        if before.endswith(('per', 'super')) and re.match(r'fe(?:ct|it|$)', s):
            return -9.0
        if before.endswith('fe') and s.startswith('ast'):
            return -8.0
        if before.endswith('fe') and (s.startswith(('ct', 'kt')) or s == 'k'):
            return -5.3
        if before.endswith('pro') and s == 'fe':
            return -6.0
        if before.endswith('def') and s.startswith('ected'):
            return -8.5
        if before.endswith('proph') and s.startswith('et'):
            return -6.0
        if before.endswith('f'):
            if re.fullmatch(r'e[ck]t', s):
                return -1.7 if before.endswith('eff') else -9.0
            if re.fullmatch(r'e[ck]', s):
                return -6.0
            if s == 'ei':
                return -5.5
            if re.match(r'e[ck]t', s):
                return -2.0 if before.endswith('eff') else -4.0
            if re.fullmatch(r'e(?:tt?|st)', s) or s.startswith(('etti', 'etto')):
                return -3.8
            if s.startswith('it'):
                return -1.9
            if s == 'e':
                return -2.2
            if s.startswith('e'):
                return -0.6
        if before.endswith('fe') and s.startswith('it'):
            return -5.2
        if before.endswith('fa') and s.startswith('it'):
            return -3.1
    if word.startswith('fect'):
        return -3.9
    if re.fullmatch(r'(?:e?fe|fe[cst]|fest)', word):
        return -1.5
    if word.startswith(('festival', 'feet', 'fees', 'fever', 'feather')):
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    s = spelling(raw)
    value = response(s, before)
    # Keep only an alphabetic suffix, never another document or sentence.
    tail = re.search(r'[a-z]+$', before + s)
    tail = tail.group()[-24:] if tail else ''
    if '完美' in raw:
        value = -3.1
    if '··' in raw:
        value = -1.68
    return (doc, tail), value

"""Approximate quantity endings: measurement units, rates, counts and clock times.

Readable spelling/context rules add calibrated strengths. A short byte tail joins
split unit names and UTF-8 characters, resetting at each document boundary.
Printf conversions, title colons and dotted rules have separate small rules.
Weak, general word-specific variation is deliberately left out.
"""
import re
import inflect
from functools import lru_cache
from anyascii import anyascii

READS = ()

_inflect = inflect.engine()
CARDINALS = list(range(1, 20)) + list(range(20, 100, 10))
CARDINALS += [100, 1000, 10**6, 10**9, 10**12]
NUMBER_WORDS = {word for n in CARDINALS
                for word in _inflect.number_to_words(n).split()}
NUMBER_WORDS.update('few several half quarter dozen'.split())
RECENT_QUANTITY = re.compile(r'\d|\b(?:' + '|'.join(
    NUMBER_WORDS | {'once', 'twice', 'times'}) + r')\b', re.I)
SCALES = set('hundred thousand million billion trillion'.split())
SHORT_TIME = set('second seconds minute minutes hour hours'.split())
LONG_TIME = set('day days week weeks month months year years'.split())
COUNT_UNITS = set('''character characters word words copy copies unit units
    piece pieces item items part parts page pages point points pixel pixels
    bit bits byte bytes record records sample samples'''.split())
LENGTH_ENDINGS = set('long wide high tall deep thick across'.split())
METRIC_BASES = '''meter metre metro metri gram gramme liter litre litro
    watt volt ampere amp joule hertz pascal newton ohm farad henry kelvin
    mol mole molar calorie calory byte bit bps gauss tesla bar curie'''.split()
PREFIXES = '''nano micro milli mili centi deci deca hecto kilo quilo mega
    giga tera pico femto'''.split()
OTHER_UNITS = """inch foot yard mile pound ounce ton tonne acre gallon pint
    quart stone carat angstrom degree percent percentage cent dollar euro yuan yen
    ruble rupee peso""".split()
UNIT_WORDS = {form for word in OTHER_UNITS
              for form in (word, _inflect.plural(word))}
for base in METRIC_BASES:
    for pre in [''] + PREFIXES:
        UNIT_WORDS.update((pre + base, pre + base + 's'))
UNIT_PREFIXES = {w[:i] for w in UNIT_WORDS for i in range(3, len(w))}
SYMBOL = re.compile(
    r'(?:[fpnumcdhkMGTµμ]?(?:m|g|l|L|s|h|M|W|V|A|J|Hz|Pa|N|F|K|B|b|mol)'
    r'|(?:cm|mm|km|m)s|mph|kph|µ|μ|Ω|Å|C|F|K|M|eV|Da|kDa|ms'
    r'|sec|secs|min|mins|hr|hrs|ft|yd|mi|in|oz|lb|lbs|ppm|ppb|psi|rpm|cc)')
CJK_UNITS = set('米克吨噸升元円원倍万萬億亿兆尺寸里镑磅亩畝分安斤')
CJK_UNITS.update('千米 公里 厘米 毫米 平方米 公斤 千克 毫克 毫升'.split())

@lru_cache(maxsize=32768)
def unit_kind(word):
    """Spelled-out units, conventional symbols, or a fragment of a unit name."""
    latin = anyascii(word).lower()
    if latin in UNIT_WORDS:
        return 'unit'
    if SYMBOL.fullmatch(anyascii(word)) or SYMBOL.fullmatch(word):
        return 'symbol'
    if latin in UNIT_PREFIXES:
        return 'unit_fragment'
    return ''

UNIT_STRENGTH = {'unit': 0.2, 'symbol': 0.24, 'unit_fragment': -0.01}
NUMBER_GAIN = {'unit': 0.92, 'symbol': -0.2, 'unit_fragment': 0.33}

def activation(tail, token, start=False):
    clean = token.strip()
    low = clean.lstrip('-–').lower()
    before = tail.rstrip()
    recent_quantity = bool(RECENT_QUANTITY.search(tail[-45:]))
    whole = tail + token
    value = 0.0
    if start:
        value -= 0.12
    if len(clean) >= 2 and set(clean) == {'·'}:
        value -= 1.73
    if clean == ':' and before == 'Title':
        value += 4.88
    # Complete a word split across tokenizer pieces.
    match = re.search(r'([A-Za-zÀ-žµμΩ]+)\Z', whole)
    word = match.group(1) if match else clean
    preceding = whole[:match.start()] if match else tail
    previous = re.search(r'([A-Za-z]+)\W*$', preceding)
    previous_word = previous.group(1).lower() if previous else ''
    number = bool(re.search(r'\d[\s\-–°]*$', preceding))
    number = number or previous_word in NUMBER_WORDS
    kind = '' if word.lower() in ('am', 'pm') else unit_kind(word)
    squared = previous_word in ('square', 'cubic', 'sq')
    continued = bool(token and tail
                     and token[0].isalpha() and tail[-1].isalpha())
    if kind:
        # Single-letter symbols need quantitative context: "a" is not amperes.
        active = (number or squared or len(word) > 2
                  or word in ('ms', 'ft', 'cm', 'mm', 'km'))
        if active:
            value += UNIT_STRENGTH[kind]
            if number:
                value += NUMBER_GAIN[kind]
                # Letter labels and the preposition 'in' are ambiguous.
                unambiguous = word not in ('in', 'A', 'B', 'b', 's')
                unambiguous |= word == 'in' and not token[:1].isspace()
                if kind == 'symbol' and unambiguous:
                    if token[:1].isspace() or len(word) > 1:
                        value += 0.81
            if continued:
                value += 0.08
                if number:
                    value += 1.0
                    if kind == 'symbol':
                        value += 1.0
            if squared:
                value += 1.77
                if recent_quantity:
                    value += 0.9
    if low in SHORT_TIME | LONG_TIME:
        value += 0.09 if low in SHORT_TIME else -0.01
        if number:
            value += 0.24
        if re.search(r'\b(?:a|an|per|each|every)\s*$', tail, re.I):
            value += 0.29
            if re.search(r'\bper\s*$', tail):
                value += 0.92
            if recent_quantity and re.search(r'\b(?:a|an)\s*$', tail):
                value += 1.62
                amount = re.search(r'(\w+)\s+(?:a|an)\s*$', tail)
                if amount and low in ('day', 'week', 'hour', 'second', 'minute'):
                    word_before_a = amount.group(1).lower()
                    plural = (word_before_a.endswith('s')
                              and word_before_a not in ('is', 'was', 'has', 'does'))
                    if plural or word_before_a in NUMBER_WORDS | {'once', 'twice'}:
                        value += 1.8
    if low == 'time' and re.search(r'\bat a\s*$', tail, re.I):
        value += 0.61
        if recent_quantity:
            value += 1.86
    if low in COUNT_UNITS and number:
        value += 0.34
    if low in SCALES:
        value += 0.65
    if low in ('square', 'cubic') and number:
        value += 1.08
    if low in LENGTH_ENDINGS:
        last_word = re.search(r'([A-Za-zÀ-ž]+)\s*$', tail)
        if last_word and unit_kind(last_word.group(1)):
            value -= 0.14
            if recent_quantity:
                value += 2.39
        elif (last_word and recent_quantity
              and last_word.group(1).lower() in COUNT_UNITS):
            value += 2.39
    if clean in ('am', 'pm', 'AM', 'PM', '.m', '.M'):
        if re.search(r'\d\s*(?:[aApP])?$', tail):
            value += (3.2 if token[:1].isspace() or clean.startswith('.')
                      else 2.1)
    if '%' in clean or '％' in clean:
        value += 0.25
        if re.search(r'\d\s*$', tail):
            value += 0.59
    if '°' in clean or clean in ('℃', '℉'):
        value += 0.72
    if (clean in ('C', 'F', 'K')
            and re.search(r'(?:[°℃℉•]|degrees?)\s*$', tail)):
        value += 1.7
    if re.fullmatch(r'[vdfsxXqTt]', clean) and re.search(r'%[-+#0-9. ]*$', tail):
        value += 1.03
    if clean in CJK_UNITS:
        value += 0.27
        if re.search(r'[\d千万萬亿億兆百公毫厘分만억천백]\s*$', tail):
            value += 1.15
        if re.search(r'[公毫厘]$', tail) and clean in set('分米升克斤里安'):
            value += 3.24
        if tail.endswith(('平方', '立方')):
            value += 2.0
    if clean in ('左右', '以上', '以下') and re.search(r'\d.{0,8}$', tail):
        value += 2.16
    if clean in set('个枚辆台匹件人名歳歲天匙条锭') and re.search(r'\d\s*$', tail):
        value += 1.06
    if low in ('per', 'each', 'every') and recent_quantity:
        value += 0.4
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    old_bytes = b'' if start else carry[1]
    new_bytes = old_bytes + prefix.token_bytes[-1]
    tail = old_bytes.decode('utf-8', errors='ignore')
    text = new_bytes.decode('utf-8', errors='ignore')
    token = text[len(tail):]
    value = activation(tail, token, start) if token else 0.0
    return (doc, new_bytes[-400:]), float(value)

