"""Fires on the word or symbol right after a number that names what the number counts or
measures: a clock time (9:30 am), a unit (20 cm, 5 %, 3 kg), or a counting noun (2 million,
3 people). Strongest for clock times and metric or imperial measures; weaker for spans of
time (3 days, 2 years) and for the bare letter m or g. Predicts 0 elsewhere."""
READS = ()
CLOCK = {"am", "pm", "a.m", "p.m"}
MEASURE = {
    "mm", "cm", "km", "mi", "miles", "mile", "feet", "foot", "ft", "inches", "inch", "yards",
    "kg", "mg", "lb", "lbs", "pounds", "pound", "oz", "ounces", "stones", "ml", "mb", "kb",
    "ppm", "°c", "°f", "μm", "µ", "nm", "kw", "hz", "khz", "mhz", "ghz", "ms", "per",
}
COUNT = {"million", "billion", "cent", "euro", "dollar", "people", "万", "萬", "円", "人", "枚",
         "件", "辆", "分", "公", "升", "公升", "毫", "%", "percent"}
SPAN = {"sec", "min", "minutes", "hour", "hours", "day", "days", "seconds", "month", "months",
        "year", "years", "second"}
SHORT = {"m": 0.6, "g": 0.4}
VALUE = {}
for group, v in [(CLOCK, 2.5), (MEASURE, 1.2), (COUNT, 1.0), (SPAN, 0.4)]:
    for u in group:
        VALUE[u] = v

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip().lower()
    prev = toks[-2] if len(toks) > 1 else ""
    if cur in SHORT:
        return carry, (SHORT[cur] if prev[-1:].isdigit() else 0.0)
    if cur in VALUE and any(ch.isdigit() for s in toks[-3:-1] for ch in s):
        return carry, VALUE[cur]
    return carry, 0.0

