"""Approximate a lexical response to 提/題, Korean 제 and Vietnamese đề.

Distinguish common compounds and their token boundaries, remembering one token.
A byte decoder also recognizes a few negative split-character patterns: Japanese
し followed by partial hiragana, Greek epsilon with smooth breathing, and partly
encoded Korean h/eu-ui syllables at word starts. Doubled middle-dot filler and
opening Title headings have separate negative responses. Other inputs get zero;
this does not recover the component's many other character-specific effects.
"""
import codecs
import unicodedata

READS = ()


def lexical(text, previous):
    word = text.strip()
    if word == '··':
        return -1.58
    if word == '提':
        return 3.2 if text.startswith(' ') else 6.1
    if '提出' in word:
        return 2.8 if word.endswith('的') else 4.4
    if '提高' in word:
        return 4.3 if word.startswith('不断') else 3.2
    if '提升' in word:
        return 2.0
    if word == '前提':
        return 3.5
    if word == '有所帮助':
        return 2.7
    if previous.strip() == '提' and word in ('着', '著'):
        return 3.5
    if word == '堤':
        return 3.2
    if word == '題':
        if previous.endswith('放'):
            return 8.0
        if previous.endswith(('話', '课', '課', '出')):
            return 6.0
        return 1.5
    if word == '题':
        return 3.8 if previous.endswith('出') else 1.8
    if '題' in word or '题' in word:
        if '问题' in word or '問題' in word:
            return 0.5
        if word in ('主題', '主题', '话题', '話題', '标题', '標題'):
            return 1.3
        return 1.7
    if word == '제':
        if text.startswith(' '):
            return 3.3
        if previous.endswith(('문', '국', ' 미', '\n')):
            return 3.0
        return 1.4
    if word == '출' and previous.strip() == '제':
        return 3.7 if previous.startswith(' ') else 1.2
    if word == '문제':
        return 1.5
    if word.lower() == 'đề' or (word == 'ề' and previous in ('Đ', 'đ')):
        return 0.5 if previous.strip() == 'vấn' else 6.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
        decoder = codecs.getincrementaldecoder('utf8')('replace')
    else:
        _, previous, position, decoder = carry
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    completed = decoder.decode(raw)
    pending = decoder.getstate()[0]
    value = lexical(text, previous)

    # Some responses occur inside a character split into several byte tokens.
    if raw and 0x80 <= raw[0] < 0xc0:
        if previous.startswith('し') and previous.endswith('�'):
            value = -0.85
        if completed:
            letters = unicodedata.normalize('NFD', completed[-1])
            if letters.startswith('ε') and '\u0313' in letters:
                value = -0.95  # Greek epsilon with smooth breathing.
        if len(pending) == 2 and 0xe0 <= pending[0] < 0xf0:
            # Two UTF-8 bytes specify a 64-codepoint interval.
            base = ((pending[0] & 15) << 12) | ((pending[1] & 63) << 6)
            letters = unicodedata.normalize('NFD', chr(base + 32))
            if previous.startswith(' ') and letters.startswith(('흐', '희')):
                value = -2.7  # Word-initial h + eu/ui, still partly encoded.
    if position == 0 and text == 'Title':
        value = -0.6
    if position == 1 and text == ':' and previous == 'Title':
        value = -4.7
    return (doc, text, position + 1, decoder), value

"""A negative response to larger digits after 8, weaker after 0 or 7.

The new digit's value controls strength: 2 has a small response, strength
rises roughly linearly from 3 to 7, then levels off. The prefix 18 amplifies
it; repeated 8s weaken it. A point or comma can separate the digits.
An 8 at the start of a row/document has reduced strength.
Other text gets zero. State resets between documents.
"""

READS = ()
DIGITS = '0123456789'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, older = None, None
    else:
        _, previous, older = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in DIGITS:
        digit = int(token)
        strength = (1.25 if digit == 2 else
                    max(0, 1.7 + 1.31 * (min(digit, 7) - 3)))
        strength += 0.3 * max(0, digit - 7)
        if previous == '8':
            if older is None:
                scale = 0.3  # The 8 began the document or row.
            elif older == '1':
                scale = 1.15
            elif older == '8':
                scale = 0.73
            elif len(older) == 1 and older in DIGITS:
                scale = 0.88
            else:
                scale = 1.03
            value = -scale * strength
        elif previous == '0':
            value = -0.17 * strength
        elif previous == '7':
            value = -0.1 * max(0, digit - 6) ** 2
        elif older == '8' and previous in ('.', ','):
            value = -strength * (0.71 if previous == '.' else 0.48)
    return (doc, token, previous), value

"""A partial orthographic approximation, not a semantic/topic detector.

Training examples show large responses at several unrelated spelling joins,
space-prefixed UTF-8 character fragments, and initial formatting tokens.
The rules below assign fixed values to those cases and zero elsewhere.
Byte tests distinguish fragments which all decode alone as '�'. Repeated
initial tokens retain the initial response; state resets between documents.
Many other character-specific responses are deliberately left unmodeled.
"""

import unicodedata

READS = ()
END = b'<|endoftext|>'


def step(carry, prefix, upstream):
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    prev = b'' if reset else carry[1]
    initial = reset or prev == END or (carry[2] and b == prev)
    state = (doc, b, initial)
    value = 0.0

    if initial:
        if b in (b'\n', b'\r', b'\t'):
            value = 0.9
        elif b == b'\\t':
            value = 3.45
        elif b == b'\\n':
            value = 1.48
        elif b == END:
            value = 1.75
        elif b == b'//\n':
            value = 2.37
        elif b in (b'"""', b'"""\n'):
            value = 1.9
        elif s in ('¿', '¡'):
            value = 2.1
        elif len(s) == 1 and s.isascii() and s.isalpha():
            value = 0.27 if s.islower() else 0.32
        elif s in ('$', '@'):  # Identifier sigils.
            value = 1.0
        elif s in ('`', '<'):  # Code/markup openers.
            value = 1.0
        elif len(s) == 1 and s in '}]':
            value = -0.74
        elif s in ('"', '\\'):  # Quotes and escape introducers.
            value = 0.6
        elif s in ('*', '_'):  # Markdown emphasis markers.
            value = 0.6
        elif s == '··':
            value = 1.50
        elif s.isspace():
            value = 0.2
        elif s.isascii() and s.isdigit():
            value = 0.2
        elif s.strip().isascii() and s.strip().isalpha():
            value = 0.35 if s.startswith(' ') else 0.15
        elif len(s) == 1:
            category = unicodedata.category(s)
            if category == 'Pi' or s == '„':
                value = 1.3
            elif category == 'Pf':
                value = 0.8
            elif category == 'Pd':
                value = 0.3
            elif category == 'Po' and s not in '.;。':
                value = 0.25
        return state, value

    if s == '··' and prev.decode('utf-8', 'replace') == '··':
        return state, 1.50

    # Persian ār/ān joins, including the root kār (work) and -gān.
    previous = prev.decode('utf-8', 'replace')
    if s == 'ار':
        if previous.strip() == 'ک':
            value = -2.55 if previous.startswith(' ') else -1.50
        elif previous.strip() in ('پ', 'ج'):
            value = -1.3
    elif s == 'ان' and previous.strip() == 'گ':
        value = -1.3

    # Latin-script qu+a joins, particularly Vietnamese quan and quay.
    if previous.strip().lower() == 'qu':
        if s == 'an':
            value = -2.0
        elif s == 'ay':
            value = 1.8 if previous.startswith(' ') else 0.5
        elif s in ('a', 'y'):
            value = -0.8

    # Thai long-aa/tone-mark join after ค, sometimes prefixed by เ.
    if s == '้า':
        if previous == 'ค':
            value = -2.0
        elif previous == 'เค':
            value = -0.88

    # Space-prefixed Han characters split after their first UTF-8 byte.
    # These blocks mostly contain water-, hand- and mouth-radical Han.
    if prev == b' \xe6':
        if b == b'\xb1':       # 江, 汕, 汤 ... (unfinished)
            value = 2.4
        elif b == b'\x90':     # 搀 ... 搿 (unfinished)
            value = 3.5
    elif prev == b' \xe5' and b == b'\x98':  # 嘀 ... 嘿
        value = 5.0

    # A split text-style Unicode variation selector (VS15).
    if prev == b'\xef\xb8' and b == b'\x8e':
        value = -2.7

    # The Korean doubled-t syllables 떠/떼, also split into bytes.
    if prev == b' \xeb' and b == b'\x96':
        value = 1.35
    # Doubled-k syllable fragments, for rounded Korean vowels.
    elif prev == b' \xea':
        if b == b'\xbd':
            value = 1.2
        elif b == b'\xbe':
            value = 2.4

    # Complete 꾸/꽤: doubled k with u/wae and no final consonant.
    if len(b) == 1 and 0x80 <= b[0] < 0xc0 and len(prev) == 1:
        if prefix.position >= 2 and prefix.document_ids[-3] == doc:
            tail = b''.join(prefix.token_bytes[-3:])
            if tail.startswith(b' '):
                syllable = tail.decode('utf-8', 'ignore').strip()
                if syllable == '꾸':
                    value = 2.1
                elif syllable == '꽤':
                    value = 1.3
    return state, value

"""A sparse approximation to surface-form responses, not a semantic classifier.

Recognize TeX openings, backslash-escaped star annotations, online-publication
phrases, PDF suffixes, and document openings. Leave other lexical variation
near zero. An escaped closing bracket after another closing bracket is negative.
Only the preceding token and a short text suffix are retained.
"""

READS = ()
PERSONAL_SUBJECTS = {'i', 'you', 'he', 'she', 'we', 'they'}
ESCAPED_STARS = {
    '*': -0.26,
    '*\\': -0.6,
    '**': -6.0,
    '*,': -0.8,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    word = token.strip()
    value = 0.002

    if first:
        if token in {'\\n', '\\t'}:
            value = 1.28
        elif token == '\\"':
            value = 2.36
        elif token == '//\n':
            value = 3.31
        elif token.startswith(('"""', "'''")):
            value = 0.72 if '\n' in token else 1.5
        elif token == 'public':
            value = 1.5
        elif token == 'package':
            value = 0.53
        elif token in {'import', 'from', '#include'}:
            value = -0.48
        elif word.lower() in PERSONAL_SUBJECTS:
            value = 0.53
        elif word.lower() in {'a', 'an', 'the'}:
            value = 0.2
        elif token == 'aligned':
            value = 0.9
        elif token == '(\\':
            value = 2.8
    elif word.lower() == 'online':
        value = -0.15
        if previous.strip() == 'Published':
            value = 3.9
        elif previous.strip() == 'Article':
            value = 1.8
        elif tail.endswith('for full'):
            value = 1.5
    elif token == 'display' and previous.endswith('\\'):
        if tail.endswith('${\\'):
            value = 2.25
        elif previous.strip() == '$\\':
            value = 0.52
        elif previous.strip() == '{\\':
            value = 0.65
        else:
            value = 0.13
    elif previous.strip() == '\\' and token in {'(\\', '((', '([', '(-'}:
        value = 3.2 if token in {'((', '(['} else 2.5
        if token == '(-':
            value = 2.2
    elif previous.endswith('\\') and token in ESCAPED_STARS:
        value = ESCAPED_STARS[token]
    elif token == ']' and previous == ']\\':
        value = -2.5
    elif token == '.pdf':
        value = -0.5
    elif token == 'aligned' and tail.endswith('\\begin{'):
        value = 0.75
    elif token == 'li' and previous.endswith('</'):
        value = 0.7
    elif word in {'//', '$$', '**'}:
        value = 0.13

    return (doc, token, (tail + token)[-40:]), value

"""A spelling-fragment heuristic, not a general detector of air-related words.

Strong negatives mark aer/aero fragments, split a-er/ana-er, and related
Greek, Cyrillic and Katakana spelling continuations. Smaller positives mark
split 'e-ach', botanical '-aceae', space-prefixed 'om', and repeated middle
dots. Romanian short a-fragments, articles and endings get positive values
after Romanian language cues have appeared. Document-initial hash headings
and // newline comments have separate values. Other positions are near zero;
context-dependent changes in response strength are not modeled.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
ROMANIAN_WORDS = frozenset((
    'pentru', 'acest', 'aceste', 'acesta', 'sunt', 'lui',
    'care', 'mai', 'din', 'cu', 'si', 'este',
))
ROMANIAN_STRONG = frozenset(('pentru', 'acest', 'aceste', 'acesta'))


@lru_cache(maxsize=20000)
def spelling(text):
    return anyascii(text).strip().lower()


def predict(previous, text, start, romanian):
    if start:
        if text.startswith('//\n'):
            return -1.7
        return 0.59 if text.startswith('#') else 0.0

    p = spelling(previous).lstrip("./_-\"'(")
    c = spelling(text)
    value = -5.73 if text.strip().lower() in ('aer', 'aero') else 0.0
    continuation = bool(text and text[0].isalpha())
    if continuation:
        # Latin a-initial fragments, especially a-e(-r) across a token split.
        latin_previous = previous.strip().lstrip("./_-\"'(")
        if re.fullmatch(r'[A-Za-z]+', latin_previous) and re.match('[A-Za-z]', text):
            if re.fullmatch(r'a[a-z]{0,2}', p):
                if p == 'a':
                    value -= 0.19
                if p in ('a', 'an', 'ana') and c.startswith('e'):
                    value -= 1.44
                if p != 'aer' and (p+c).startswith(('aer', 'anaer')):
                    value -= 6.06
        if previous.strip().lower() in ('aer', 'aero'):
            value -= 2.2
        if p.endswith('e') and c == 'ach':
            value += 0.58
        if p.endswith('ace') and c == 'ae':
            value += 1.17

        # Cyrillic/Greek a, Cyrillic e-ro, and Katakana a / e-a / e-ro.
        if previous.strip() in ('а', 'А', 'α', 'Α'):
            value -= 0.28
            if c.startswith('e'):
                value -= 3.87
        if previous.strip() in ('э', 'Э'):
            value -= 0.33
            if text.startswith('ро'):
                value -= 5.17
        if previous.endswith('ア'):
            value -= 0.70
        if previous.endswith('エ') and text.startswith(('ア', 'ロ')):
            value -= 3.16

    if text and set(text) == {'·'} and previous and set(previous) == {'·'}:
        value += 1.15
    if text.startswith(' ') and c == 'om':
        value += 0.70
    if romanian:
        if text.strip().lower().startswith('a') and len(c) <= 4:
            value += 0.56
        if text.strip().lower() == 'a':
            value += 1.78
        if text.startswith(' ') and c in ('al', 'ale', 'ai'):
            value += 4.00
        if text.startswith(' ') and c in ('o', 'un', 'unei', 'unor'):
            value += 2.88
        if continuation and c in ('or', 'elor', 'i'):
            value += 0.52
            if (p == 'acest' and c == 'or') or (p == 'une' and c == 'i'):
                value += 3.19
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        previous, seen, romanian, tail = '', frozenset(), False, b''
    else:
        previous, seen, romanian, tail = carry[1:]
    if '\ufffd' in previous:
        previous = tail.decode('utf-8', 'ignore')[-1:]
    text = prefix.token_strings[-1]
    value = predict(previous, text, start, romanian)

    # Causal language evidence, reset along with the document.
    word = text.strip().lower()
    if word in ROMANIAN_WORDS:
        seen = seen | {word}
    romanian = (romanian or word in ROMANIAN_STRONG or len(seen) >= 4
                or any(ch in text for ch in 'șȘțȚ'))
    tail = (tail + prefix.token_bytes[-1])[-16:]
    return (doc, text, seen, romanian, tail), float(value)

"""Detect boundaries in fragmented indentation, especially a lone tab.

Tabs and tab-prefixed words are positive at the start of indentation, but
negative when extending a previous tab. Code punctuation just after one tab
is strongly positive; deeper indentation suppresses that response. Mixed
ordinary/nonbreaking spaces produce similar signed boundary responses.
Digits before tabs strengthen the negative response (as in numbered listings).
Smaller rules cover escaped tabs and code marks or short alphabetic fragments
after nonbreaking spaces. Other text gets zero. The two-token memory resets
at document boundaries.
"""
READS = ()


def tab_indentation(s):
    return bool(s) and not s.strip(' \t') and '\t' in s


def nonbreaking_spaces(s):
    return bool(s) and not s.strip('\xa0')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, prev, before = carry if carry and carry[0] == doc else (doc, '', '')
    s = prefix.token_strings[-1]
    value = 0.0
    if s.startswith('\t'):
        if '\n' in s or '\r' in s:
            value = 1.0 if s.count('\t') == 1 else 0.4
        elif s == '\t':
            if prev == '\t':
                value = -3.0 if before.isdigit() else -1.4
            else:
                value = -0.15 if tab_indentation(prev) else 0.7
        elif s.isspace():
            value = 0.0
        elif prev == '\t':
            value = -2.4 if before.isdigit() else -1.25
        else:
            value = -0.4 if tab_indentation(prev) else 0.7
    elif prev == '\t':
        if tab_indentation(before):
            value = 0.15
        elif s.isspace():
            value = 1.1
        elif s.startswith('}'):
            value = 4.0 if before.startswith('}') else 2.7
        elif s.startswith(('//', '#', '<', ')', ']')):
            value = 2.4
        elif s.startswith(('"', "'", '$', '/', '*', '&', '@', '(')):
            value = 1.6
        elif s.startswith(' '):
            value = -0.5
        else:
            value = 0.3
    elif s == '\xa0':
        if prev == ' ':
            value = -5.5 if '\xa0' in before else -0.7
        elif nonbreaking_spaces(prev):
            value = -0.7 if nonbreaking_spaces(before) else 1.7
        else:
            value = 0.1
    elif '\xa0' in s and s.isspace():
        if s.startswith(' '):
            value = -3.0 if ' ' in prev and '\xa0' in prev else -0.85
        elif nonbreaking_spaces(prev):
            value = -1.2
    elif prev == '\xa0':
        if s == '`':
            value = 2.6
        elif s == '``':
            value = 0.6
        elif s and s[0].isalpha() and len(s) <= 2:
            value = 0.8
    elif prev == '\\t':
        value = 1.6 if s.startswith('}') else 0.0
    elif s.startswith('}') and s.endswith('\\') and prev in ('n', '\\n'):
        value = 0.65
    elif s == '\\t':
        value = -0.15
    return (doc, s, prev), value

"""An opening-token lexical pulse, switching to zero after distinct context arrives.

Case, word length, English word frequency and closed grammatical classes
approximate the pulse's sign and size. Capitalized common words tend positive;
lowercase content words tend negative. Individual words still vary substantially.
An initial repetition keeps the pulse alive; a document boundary restarts it.
"""
import unicodedata
from wordfreq import zipf_frequency

READS = ()

# Closed grammatical classes, not a vocabulary of fitted content words.
LINKING_WORDS = set('''
of to in for on with at from by as into about over under between through after
before without against during within upon and or but nor so yet if because
although while when unless than whether be am is are was were been being
i you he she it we they me him her us them my your his its our their mine yours
'''.split())
AUXILIARIES = set('''
have has had do does did will would shall should can could may might must
'''.split())
DETERMINERS = set('''
this that these those any some each every no all both either neither another
other such
'''.split())
QUESTIONS = set('who what which where why how whose whom'.split())


def opening_value(s):
    w = s.strip()
    if s.startswith('<|') and s.endswith('|>'):
        return -1.65
    if not w:
        return 0.9 if s == ' ' else (-1.0 if '\n' in s else 0.1)
    if '\ufffd' in w:
        return -6.3
    if w.isdigit():
        return -0.2 if all(c in '012' for c in w) else -2.0
    if all(unicodedata.category(c)[0] in 'PS' for c in w):
        return -0.9
    if not w.isascii():
        return -3.4
    if not w.isalpha():
        return -2.8
    low = w.lower()
    n = len(w)
    spaced = s.startswith(' ')
    if low == 'the':
        return 7.9 if w.istitle() else (4.0 if spaced else 6.9)
    if low in {'a', 'an'}:
        return 2.2 if w.istitle() else 0.45
    if w.istitle():
        if n == 1:
            return 4.4
        return 1.3 * zipf_frequency(low, 'en') - 6.3
    if w.isupper():
        return 0.9
    if low in LINKING_WORDS:
        return 0.25
    if low in AUXILIARIES:
        return -2.1
    if low in DETERMINERS:
        return -2.9
    if low in QUESTIONS:
        return -1.1
    if n == 1:
        return -0.9 if spaced else 3.1 * zipf_frequency(low, 'en') - 15.4
    if n <= 3:
        return -3.7 if spaced else -2.1
    return -5.1 if spaced else -4.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, opening_value(prefix.token_strings[-1]))
    elif token != carry[1]:
        carry = (doc, token, 0.0)
    return carry, carry[2]

"""Recognize command-line text: command names at shell boundaries, interactive
prompts, executable relative paths, and the interpreter in a shebang.

The response depends on both the utility and its left-hand syntax. Pipes strongly
mark head/tail/grep; inline `cat` is especially strong. Other text is mostly zero.
Only a short text suffix is carried, and it resets at document boundaries.
"""
import re

READS = ()

# Utility responses: opening quote, inline backtick, command chain, pipeline.
COMMANDS = {
    'cat':     (2.20, 4.55, 2.50, 3.30),
    'grep':    (0.95, 1.10, 1.20, 3.35),
    'head':    (0.20, 0.30, 0.45, 2.20),
    'tail':    (0.65, 0.70, 0.70, 3.30),
    'cd':      (0.95, 1.15, 1.35, 1.35),
    'python':  (0.90, 0.30, 2.10, 2.10),
    'git':     (0.80, 1.15, 0.95, 0.95),
    'sudo':    (2.10, 2.10, 2.20, 3.20),
    'awk':     (1.10, 1.10, 1.10, 1.10),
    'php':     (0.50, 0.25, 1.45, 1.45),
    'sed':     (0.65, 1.40, 1.35, 1.90),
    'yarn':    (1.50, 1.00, 1.80, 1.80),
    'chmod':   (1.10, 1.30, 1.20, 1.20),
    'kubectl': (1.70, 1.70, 1.70, 1.70),
}
HOST = re.compile(r'(?:Router|Switch)\w*$|\bPC\d*$|\b[\w-]*Server$')


def command_value(token, before):
    name = token.strip()
    q, inline, chain, pipe = COMMANDS[name]
    p = before.rstrip(' \t')
    spaced = token[0].isspace()
    if not before:
        return 0.0
    if not spaced and (before[-1].isalnum() or before[-1] == '_'):
        return 0.0
    if p.endswith('|') and not p.endswith('||'):
        return pipe
    if p.endswith(('&&', '||', ';')):
        return chain
    if p.endswith('`'):
        return inline
    if p.endswith(('"', "'")):
        return q
    if p.endswith(('$', '!')):
        return chain + 2.7 if spaced else q
    if re.search(r'\b(sudo|exec|xargs)\s*$', before):
        return 0.45 if name == 'python' else chain
    if p.endswith(('\n', '\\n', '\r')):
        if name == 'cat':
            return 1.0
        return 0.7 if name == 'cd' else q
    if re.search(r'\b(run|running|execute|using|use)\s*$', before):
        return 1.6 if name == 'python' else q
    return {'git': 0.32, 'grep': 0.60, 'awk': 1.10,
            'sudo': 1.10}.get(name, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    p = before.rstrip(' \t')
    line = before.rsplit('\n', 1)[-1]
    value = 0.0
    if token.strip() in COMMANDS:
        value = command_value(token, before)
    elif token == ')#' and re.search(r'\(config(?:-[\w-]+)?$', before):
        value = 10.1  # Network-device configuration prompt.
    elif token == '(config' and HOST.search(line):
        value = 4.2
    elif token == '#' and HOST.search(line):
        value = 8.0
    elif token == ')' and before.endswith('(gdb'):
        value = 16.0
    elif token == '>' and re.search(r'\b(mysql|scala|sqlite)$', line):
        value = 7.0
    elif token == '>' and line.endswith('*Main'):
        value = 5.0
    elif token.strip() == '>>>':
        value = 1.05 if token[0].isspace() else (1.55 if p.endswith('`') else 0.46)
    elif token == ' ./':
        if p.endswith('$'):
            value = 8.3
        elif p.endswith('RUNS'):
            value = 4.0
        elif p.endswith(('&&', ';')):
            value = 2.4
        elif p.endswith(('\n', '\\n')):
            value = 3.0
        elif re.search(r'\b(go (test|build)|node|tsc|rm)\b[^;|\n]{0,80}$', p):
            value = 1.9
        elif p.endswith(('"', "'", '`')):
            value = 1.5
        else:
            value = 0.3
    elif token == './' and (p.endswith(('\n', '\\n', '`'))):
        value = 1.7
    elif token == '/env' and before.endswith('!/usr/bin'):
        value = 1.6
    elif token == '/python' and before.endswith('/bin'):
        value = 0.7
    return (doc, (before + token)[-160:]), value

