"""Shell command names that start a command lights up this component, as in `| tail`,
`` `cat `` or `&& python`; how much depends on the command. In a router CLI transcript, the `#`
prompt that follows `(config)` also lights it up."""
READS = ()

# How strongly each command name fires when it starts a command.
COMMAND_STRENGTH = {
    "cat": 4.0, "tail": 3.0, "grep": 2.2, "python": 2.0, "head": 2.0, "sudo": 2.5,
    "nano": 2.5, "vim": 1.8, "yarn": 1.8, "php": 1.4, "awk": 1.3, "chmod": 1.2,
    "git": 1.0, "cd": 1.0, "ls": 0.9, "helm": 1.0, "mkdir": 1.0, "sed": 1.0,
    "echo": 0.5, "curl": 0.6, "export": 0.4, "npm": 0.4, "cargo": 0.4, "rm": 0.3,
    "bash": 0.2, "./": 2.0,
}
# Tokens after which a command name starts a new command: a shell pipe, `&&`, a backtick,
# a quote opening a tool call's command string, or the start of a line.
COMMAND_STARTS = {"|", "&&", "||", "`", '"', "$(", ";", ""}
ROUTER_PROMPTS = {"#", ")#"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    recent = "".join(prefix.token_strings[-8:])
    if word in ROUTER_PROMPTS and "(config" in recent:
        return None, 8.0
    if before in COMMAND_STARTS:
        return None, COMMAND_STRENGTH.get(word, 0.0)
    return None, 0.0

