"""A spelling feature centered on h, especially at the end of short tokens.

Isolated h and final ch/th/ph-like spellings give negative values. Very frequent
English spellings and long tokens usually weaken the response. Small consonant
transliteration rules cover analogous short non-Latin tokens. Two separate
formatting responses are repeated middle dots and a document's Title: header.
This deliberately omits most word-specific and contextual variation.
"""
import codecs
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def spelling_value(text):
    word = text.strip().lower()
    if not word:
        return 0.0
    if set(word) == {'·'} and len(word) >= 2:
        return 1.61
    if word == '・':
        return -0.51

    # Short consonant spellings in other writing systems.
    if not word.isascii() and len(word) <= 2:
        roman = anyascii(word).lower()
        katakana = any('KATAKANA' in unicodedata.name(c, '') for c in word)
        if roman in ('chi', 'tchi', 'hi'):
            if katakana:
                return -1.3 if roman == 'tchi' else -0.95
            return -0.35 if roman == 'hi' else -0.3
        if roman in ('ch', 'sh', 'shi', 'th', 'h', 'kh', 'khi'):
            if roman.startswith('kh'):
                return -0.18
            if roman == 'h':
                return -0.5
            if roman == 'ch' and any('ARABIC' in unicodedata.name(c, '')
                                     for c in word):
                return -0.9
            return -0.4

    h = word.rfind('h')
    if h < 0:
        return 0.0
    length = len(word)
    spaced = text[:1].isspace()
    distance = length - h - 1
    pair = word[max(0, h - 1):h + 1]
    if distance:
        if h == 0 and distance == 1:
            return -0.10 if spaced else -0.41
        if pair == 'rh':
            return -0.67
        if pair == 'ch':
            return -0.24 if distance <= 2 else -0.12
        return -0.04 if distance <= 2 else -0.07

    frequency = zipf_frequency(word, 'en')
    if frequency > 6.2:
        return 0.0 if length <= 4 else -0.1
    if frequency < 0.6:
        return -0.25
    if pair == 'ch' and frequency > 3.5:
        if length <= 4:
            return -0.93
        if length <= 7:
            return -0.6 - 0.77 * (word.count('h') - 1)
        return -0.18
    if length == 1:
        return -0.71 if text.strip().isupper() else -1.09
    if length <= 3:
        return -0.40 if spaced else -0.66
    if pair == 'th' and frequency > 4.4:
        return -0.52 if frequency <= 5.6 else 0.0
    return -0.30 if length <= 5 else -0.11


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous, pending = 0, '', b''
    else:
        _, age, previous, pending = carry
        age += 1
    raw = prefix.token_bytes[-1]
    decoder = codecs.getincrementaldecoder('utf-8')('ignore')
    decoder.setstate((pending, 0))
    text = decoder.decode(raw)
    pending = decoder.getstate()[0]
    value = spelling_value(text)
    # The chi syllable can also arrive as the end of a split UTF-8 character.
    if text == 'チ' and raw and 0x80 <= raw[0] < 0xC0:
        value = -4.0
    if age == 1 and previous == 'Title' and text == ':':
        value = -7.25
    return (doc, age, text, pending), value

