each giving a fixed negative activation; every other token predicts 0."""
READS = ()
WORDS = {" such": -1.0, " much": -0.7, " perhaps": -0.7, " each": -0.8, " maybe": -0.3,
         " completely": -0.6, " North": -0.8, " South": -0.7, " south": -0.6, " north": -0.6}


def step(carry, prefix, upstream):
