"""Approximate the short response at a document's beginning.

The pulse waits through repetitions of the opening token. It is larger
inside the opening ASCII word or number, and smaller at a new capitalized
word. Length, case, whitespace and English word frequency adjust its size;
document markers have separate opening values. Later predictions approach
zero. Lexical variation outside these rules is deliberately omitted.
"""
from wordfreq import zipf_frequency

READS = ()


def ascii_word(text):
    return text.isascii() and text.isalpha()


def commonness(text):
    word = text.strip()
    if not ascii_word(word):
        return 0.0
    return max(0.0, zipf_frequency(word.lower(), "en") - 6.0)


def opening_value(text):
    word = text.strip()
    if text == '<|endoftext|>':
        return -10.24
    if text == '<|im_start|>':
        return -0.47
    if not word:
        return -0.40
    if word.isdigit():
        return 0.01
    value = 0.04 - 0.065 * min(len(word), 10)
    if ascii_word(word):
        value += 0.20 + 0.10 * commonness(text)
    if word[0].isupper():
        value -= 0.33
    if text.startswith(' '):
        value -= 0.05
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, text, 0, ascii_word(text.strip()),
                 text.strip().isdigit())
    _, first, first_text, age, word_run, digit_run = carry
    if age == 0 and token == first:
        value = opening_value(text)
    else:
        age += 1
        word_run = word_run and ascii_word(text)
        digit_run = digit_run and text.isdigit()
        if age == 1:
            value = 0.70
            if word_run:
                value = 1.40
            elif text.strip() and text.strip()[0].isupper():
                value = 0.30
            if text.strip().isdigit():
                value = 1.85 if digit_run else 1.08
            value += 0.22 * (commonness(text) - commonness(first_text))
            if first_text == '<|im_start|>':
                value = 0.43
        else:
            values = (0.0, 0.0, 0.18, 0.065, 0.03, 0.018, 0.01)
            value = values[age] if age < len(values) else -0.002
            if word_run:
                value += 0.15 * 0.2 ** (age - 2)
            if digit_run:
                value = 1.05 * 0.52 ** (age - 2)
    return (doc, first, first_text, age, word_run, digit_run), value

programs.haiku:
"""Candidate 2: document-start effect, by position and by how the first two tokens join."""

READS = ()
def _doc_pos(prefix):
    d = prefix.document_ids
    t = len(d) - 1
    k = 0
    while k < 3 and k < t and d[t - k - 1] == d[t]:
        k += 1
    return k

def _kind(s):
    if s[:1] == " ":
        return "space"
    if s[:1].isdigit():
        return "digit"
    if s[:1].isalpha():
        return "letter"
    return "other"

def step(carry, prefix, upstream):
    s = prefix.token_strings
    p = _doc_pos(prefix)
    if p == 1:
        prev, cur = _kind(s[-2]), _kind(s[-1])
        if cur == "letter" and prev == "letter":
            v = 1.7
        elif cur == "digit":
            v = 1.3
        elif cur == "space":
            v = 0.7
        else:
            v = 0.5
        return None, v
    if p == 0:
        return None, -0.2
    if p == 2:
        return None, 0.5 if _kind(s[-1]) == "digit" else 0.2
    return None, 0.0

programs.sol:
"""A sparse detector of English compound endings and ie/ies fragments.

The main positive triggers are head-words, ie/ies endings, compound endings
such as house and bound, and the Chinese word for goods. Joining an existing
word is different from using a free-standing token. English grammatical
context helps distinguish English endings from similar foreign spellings;
recovering a frequent word in -y weakens the diminutive reading of -ies.
There are also explicit web-page byline/counter/heading patterns, and a
small negative offset at the first token of each document.
Unmodelled positions receive a near-zero prediction. This is a mixed lexical
approximation, not a claim that all these triggers have one shared meaning.
"""
import re
from wordfreq import zipf_frequency

READS = ()

# (ordinary token, extra when attached to an alphabetic stem)
HEAD_WORDS = {
    'head': (0.33, 0.55),
    'heads': (1.12, 0.23),
    'headed': (2.09, -0.88),
    'heading': (0.28, -0.13),
    'headset': (0.2, 0.0),
}
OTHER_WORD_PARTS = {
    'house': (0.21, 0.90),
    'houses': (0.34, 0.42),
    'bound': (0.64, 0.88),
}
GRAMMAR = re.compile(
    r'\b(?:the|a|an|of|to|and|is|are|in|for|with|that|it|this|'
    r'he|she|they|was|were|as|on|his|her|we|you)\b'
)
NON_PHYSICAL_HEAD_WORDS = {'ahead', 'subhead', 'overhead', 'lookahead'}
DIRECTIONS = {'east', 'west', 'north', 'south', 'homeward'}


def frequency(word):
    """How familiar is this English stem, above a low-frequency floor?"""
    return max(0.0, zipf_frequency(word.lower(), 'en') - 2.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    opening = carry is None or carry[0] != document
    if opening:
        previous = stem = line = recent = ''
    else:
        _, previous, stem, line, recent = carry

    text = token.strip()
    word = text.lower().lstrip('-_')
    attached = bool(previous[-1:].isalpha() and token[:1].isalpha())
    value = -0.0008 - 0.23 * opening

    if word in HEAD_WORDS or word in OTHER_WORD_PARTS:
        ordinary, extra = (HEAD_WORDS.get(word)
                           or OTHER_WORD_PARTS[word])
        value += ordinary + extra * attached
    english = False
    if word in ('head', 'heads') or text in ('ie', 'ies'):
        english = len(GRAMMAR.findall(recent.lower())) >= 2
    if word in ('head', 'heads'):
        value += 0.49 * english
        if attached and stem.lower() + 'head' not in NON_PHYSICAL_HEAD_WORDS:
            value += 2.57 + 0.16 * frequency(stem)
    if word == 'bound':
        if stem.lower() in DIRECTIONS:
            value += 4.06
        if stem.lower() in ('upper', 'lower', 'un'):
            value -= 0.92

    if text in ('ie', 'ies'):
        value += -0.05 if text == 'ie' else 0.34
        value += 0.10 * attached + 0.10 * stem[:1].isupper()
        value += 0.32 * english
        if zipf_frequency((stem + token).lower(), 'en') >= 2.5:
            value -= 0.14
        if attached:
            value += (0.16 + 0.08 * english) * frequency(stem)
            if text == 'ies':
                value -= (0.26 + 0.09 * english) * frequency(stem + 'y')

    if text in ('货', '貨'):  # goods, simplified and traditional
        value += 3.26
    elif text in ('头', '頭'):  # head
        value += 0.31
    elif text == '盒':  # box
        value += 0.77

    # Recognizable bylines, sorting controls, and reference-section headings.
    if token == ' by':
        if previous.strip().lower() == 'posted':
            value += 0.68 + 3.36 * (line.strip().lower() == 'posted')
        if previous.strip().lower() == 'sort':
            value -= 0.40 + 2.01 * (line.strip().lower() == 'sort')
    if token == ' ones' and previous.strip().lower() == 'loved':
        value -= 1.30
    if '\n' in token and not text:
        if line.strip().lower() == 'external links':
            value -= 0.56
        elif line.strip().lower() == 'references':
            value -= 0.18
    if token == 'Views' and re.search(r'Replies:\s*[0-9]+\s*$', recent):
        value -= 1.90
    if text in ('posted', 'Posted'):
        value += 0.38

    tail = re.search(r'[A-Za-z]+$', token)
    if not tail:
        stem = ''
    elif token.isalpha():
        stem += token
    else:
        stem = tail.group()
    line = (line + token).split('\n')[-1][-100:]
    recent = (recent + token)[-100:]
    state = (document, token, stem, line, recent)
    return state, float(value)

programs.haiku:
"""Layer-1 MLP neuron 3502 (down_proj component): fires on word pieces that complete a
compound word or a name, chiefly "head" and "bound" (Radiohead, bridgehead, eastbound),
Chinese 货 / 貨 ("goods"), "house", "-ie"/"-ies" endings, and " by" after "posted";
slightly negative on web boilerplate."""

READS = ()

HEAD = {"head", "heads", "headed", "Head", "Heads", "HEAD", "thead", "-head", "-headed"}
BOUND = {"bound", "-bound", "hound", "Bound"}
GOODS = {"货", "貨"}
HOUSE = {"house", "thouse"}
IE = {"ie", "ies"}
BOILERPLATE = {"Views", "Recommended", "··"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    glued = not tok.startswith(" ") and prev[-1:].isalpha()
    word = tok.strip()
    if word in HEAD:
        value = 3.5 if glued else 0.8
    elif word in BOUND:
        value = 2.5 if glued else 0.3
    elif word in GOODS:
        value = 3.5
    elif word in HOUSE:
        value = 1.3
    elif word in IE:
        value = 0.8 if glued else 0.3
    elif tok == " by" and prev.strip().lower() == "posted":
        value = 2.0
    elif word in BOILERPLATE:
        value = -1.0
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A pulse before a document has acquired varied token context.

Emit a coarse token-type average on the first token and on consecutive
copies of it; become nearly silent as soon as a different token appears.
Pulse heights distinguish whitespace, digits, punctuation, script and
Latin capitalization. The literal subject pronoun 'I' has its own height.
Exact token-specific heights and small later activations are not modeled.
"""
import regex
from functools import lru_cache

READS = ()

# Each pair is (without leading whitespace, with leading whitespace).
LATIN_HEIGHTS = {
    'lower': (4.70, 0.70),
    'title': (5.36, 3.57),
    'upper': (7.01, 3.34),
    'mixed': (1.61, 1.61),
}


@lru_cache(maxsize=8192)
def pulse(text):
    word = text.strip()
    if text == 'I':
        return 15.68
    if text.startswith('<|'):
        return 2.27
    if not word:
        if '\n' in text or '\r' in text:
            return 0.01
        if text == ' ':
            return 3.73
        if text == '\t':
            return 3.51
        return 6.17 if set(text) == {' '} else 5.43
    if word.isdecimal():
        return 4.99
    if not any(c.isalnum() for c in word):
        return 1.55 if len(word) == 1 else 2.22
    if regex.search(r'\p{Han}', word):
        return 3.47
    if regex.search(r'\p{Cyrillic}', word):
        return 1.86
    if regex.search(r'\p{Arabic}', word):
        return 3.11
    if regex.fullmatch(r'\p{Latin}+', word):
        case = ('title' if word.istitle() else 'upper' if word.isupper()
                else 'lower' if word.islower() else 'mixed')
        return LATIN_HEIGHTS[case][int(text[0].isspace())]
    return 4.94 if word.isalpha() else 3.19


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        initial, active = token, True
    else:
        _, initial, active = carry
        active = active and token == initial
    value = pulse(prefix.token_strings[-1]) if active else -0.002
    return (doc, initial, active), value

"""Recognize a few conspicuous document-opening formats.

Approximate the opening responses to fullwidth characters, NULs, escapes,
comments, chat markers and issue-record headers. Opening Title fields have
a negative pulse. Repeated caret and middle-dot separators have positive
responses. Ordinary text gets a small baseline, not a lexical lookup.
Weak baselines distinguish scripts, unspaced fragments, and abbreviations.
This separates sharp formatting pulses from small ordinary-text responses;
it deliberately leaves token-specific lexical variation unexplained.
"""

import unicodedata
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent, separator = 0, '', ''
    else:
        position, recent, separator = carry[1] + 1, carry[2], carry[3]
    token = prefix.token_strings[-1]
    if position == 0:
        separator = token if token in ('^^^^', '··') else ''
    elif token != separator:
        separator = ''
    value = 0.0045
    word = token.strip()
    spaced = token[:1].isspace()
    if word.isascii() and word.isalpha():
        if not spaced and len(word) > 1 and word.islower():
            value = -0.011 if len(word) == 3 else -0.004
        elif not spaced and len(word) > 1 and word.isupper():
            value = -0.033 if len(word) == 2 else -0.011
        elif spaced and word.istitle() and len(word) in (3, 4):
            value = -0.014
    elif regex.search(r'\p{Script=Hiragana}|\p{Script=Katakana}', token):
        value = 0.025
    elif regex.search(r'\p{Script=Cyrillic}', token):
        value = 0.013

    if token in ('<|im_start|>', '<|im_end|>'):
        value = 0.028
    elif token == '<think>':
        value = 0.128
    elif recent.endswith('<|im_start|>'):
        if token == 'assistant':
            value = 0.040
        elif token == 'user':
            value = -0.017

    if position == 0:
        if token == '\x00':
            value = 1.83
        elif token and all(unicodedata.east_asian_width(c) == 'F' for c in token):
            value = 1.20
        elif token in ('///', '//!'):
            value = 1.30
        elif token == '&gt':
            value = 1.50
        elif token in ('>\\', '+\\'):
            value = 1.35
        elif token == '\\"':
            value = 0.98
        elif token == '<|endoftext|>':
            value = -1.26
        elif token == '<|im_end|>':
            value = -0.116
        elif token == '<|im_start|>':
            value = 0.26
        elif token == 'Title':
            value = -0.30
    if position == 1 and recent == 'Title' and token == ':':
        value = -2.17
    if recent == '<' and token == 'issue':
        value = 0.24
    if recent == '<issue_start><' and token == 'issue':
        value = 1.79
    if recent.endswith('<issue_start><issue_comment') and token == '>Title':
        value = -0.32
    if separator:
        value = 2.10 if separator == '^^^^' else 0.93

    return (doc, position, (recent + token)[-80:], separator), value

