"""Layer-1 MLP neuron 3504 (down_proj): a weak, mostly token-specific feature.

Its clearest response is at the first token of each document (the token right after a
document break, with no earlier context). There the activation is a fixed number that
depends only on that token. Roughly, it is pushed up by odd or repeated symbols, fullwidth
characters, and capitalised or non-Latin words, and pushed down by plain lowercase English
words and tab-indented fragments; a colon right after a document-opening "Title" is strongly
negative. Everywhere else the program predicts 0; the remaining
variance is small, token-specific noise with no simple pattern.
"""

READS = ()

FULLWIDTH = set(range(0xFF01, 0xFF5F))


def start_value(text):
    word = text.strip()
    if not word:
        return 0.0
    if text[:1] == "\t":
        return -0.1
    if len(text) > 1 and len(set(text)) == 1:
        return 0.25
    if any(ord(c) in FULLWIDTH for c in text):
        return 0.3
    if word.isascii() and word.isalpha() and word.islower():
        return -0.08
    if not any(c.isalnum() for c in word):
        return 0.12
    if word.isdigit():
        return 0.0
    return 0.05


def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return None, start_value(prefix.token_strings[-1])
    # A "Title:" header opening a document: the colon right after a document-initial "Title".
    if prefix.position >= 1 and prefix.token_strings[-1] == ":" and prefix.token_strings[-2] == "Title":
        if prefix.position == 1 or prefix.document_ids[-3] != prefix.document_ids[-2]:
            return None, -2.0
    return None, 0.0

