"""Negative pulses for 支 (branch/support), 枝, and the counters 只/隻.

Single characters are stronger than most compounds. Counting context boosts
只. Compounds are damped, with separate strengths for support words and Alipay.
Vietnamese chi fragments are strongly negative; an Italian-context heuristic
compares Italian and English word frequencies. TeX chi is weakly positive.
Thai ชี continuations and middle-dot-only runs have separate responses.
Other text gets 0: small token-specific background fluctuations are ignored.
Carry holds unfinished UTF-8 bytes and 80 characters of this document's text.
"""
import codecs
import re
import unicodedata
from wordfreq import zipf_frequency

READS = ()
NUMERALS = set('一二三四五六七八九十百千万亿零〇两兩几幾数數')
COUNT_ENDINGS = NUMERALS | set('这這那哪每各余餘')


def counting(text):
    text = text.rstrip()
    return bool(text) and (text[-1].isdigit() or text[-1] in COUNT_ENDINGS)


def vietnamese(text):
    # Horns, hooks above, dots below, and barred d are Vietnamese spelling hints.
    return any(c in unicodedata.normalize('NFD', text)
               for c in 'đĐ\u031b\u0309\u0323')


def response(text, recent):
    word = text.strip()
    if word == '支':
        return -9.2 if counting(recent) else -8.0
    if (word.endswith('支') and word[:-1]
            and all(c in NUMERALS for c in word[:-1])):
        return -8.0
    if '支' in word:
        if '支付宝' in word:
            return -0.6
        if '支持' in word or '支援' in word or '支撑' in word:
            return -1.25
        return -2.2
    if word == '只':
        return -3.6 if counting(recent) else -1.35
    if word == '隻':
        return -2.3
    if word.endswith('只') and counting(word[:-1]):
        return -3.2
    if '只是' in word:
        return -0.4
    if word == '枝':
        return -1.3
    if len(word) >= 2 and set(word) == {'·'}:
        return -1.0 if not recent.strip('· \t\r\n') else 0.0
    if word == 'chi':
        if text.startswith(' '):
            if vietnamese(recent):
                return -5.7
            words = re.findall(r'[^\W\d_]+', recent.lower())[-8:]
            italian = sum(zipf_frequency(w, 'it') - zipf_frequency(w, 'en')
                          for w in words) > 4
            return 0.3 if italian else -0.7
        return 0.15 if recent.endswith('\\') else -0.1
    if word == 'Chi':
        return -0.6
    if word == 'ch' and text.startswith(' '):
        return -0.9 if vietnamese(recent) else 0.0
    if text == word and word.lower() in ('i', 'hi'):
        joined = recent[-2:] + word
        if joined.lower().endswith(('chi', 'zhi')):
            return -0.4
    if word == 'ี' and recent.endswith('ช'):
        return -2.3
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        pending, recent = b'', ''
    else:
        _, pending, recent = carry
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    text = decoder.decode(pending + prefix.token_bytes[-1], final=False)
    pending = decoder.getstate()[0]
    value = response(text, recent)
    return (document, pending, (recent + text)[-80:]), value

"""Approximate a document-opening pulse, not a general semantic detector.

The pulse's size depends on readable spelling/word classes: punctuation,
pronouns and question words are strongly negative; articles are usually weaker.
An initial run of identical tokens retains the pulse.
Once other text arrives, the prediction is zero. These coarse averages leave
substantial token-specific variation unexplained.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
PRONOUNS = set('i you he she it we they me him her us them'.split())
QUESTIONS = set('who what where when why how which whom whose'.split())
DEICTICS = set('this that these those here there'.split())
GREETINGS = set('hi hello dear welcome thanks thank'.split())


def opening_value(text):
    word = text.strip()
    lower = word.lower()
    if text.startswith('<|'):
        return -2.47
    if not word:
        if '\n' in text:
            return -3.45
        return 1.87 if len(text) > 1 or '\t' in text else -0.44
    if not any(c.isalnum() for c in word):
        if word in {'.', '..', '...'}:
            return -5.89
        if any(c in word for c in '\"\'“”‘’'):
            return -4.06
        if word in {',', ';'}:
