"""layers.1.mlp.down_proj:3507: a conversational-opener feature at the start of a context.

The component is almost silent except at the first token of a context: the first token
of each row and the first token after each <|endoftext|> (a new document). There the
model's attention sees only that token, so its output depends only on which token opens
the text. Measured on training rows, that is what sets the activation:

* Spoken or chat-style openers are strongly negative: questions and exclamations
  ("What", "How", "Sure", "Hello", "Please", "Oh", "So"), emoji, "?" and "!", and Chinese
  chat particles (呢, 啊, 嘿嘿, 哎, 啥). Question marks, exclamations and emoji are about -7;
  chat openers about -6.
* Sentence punctuation (".", "#", quotes) is about -3; CJK text about -2.4.
* Formal or technical word pieces ending in -ed, -ly or -ing sit near 0, and whitespace
  tokens near -0.7.
* Any other first token is about -1.1.

Every other position predicts 0. The levels are the mean activation of each group over
training rows, rounded.
"""

CHAT_OPENERS = set(
    "I You you We He She They It How What Why Who Do Does Can Could Would Should Will "
    "Sure sure Hello Hi Hey Well Great Now Alright Yeah yeah Yes No Oh Wow Ah Hmm okay Okay "
    "Ok OK Thank Thanks Please Welcome Think think Imagine wonder wondered wondering "
    "Honestly Certainly Anyway haha huh Learn Experts Nothing Best Students Let So And But "
    "Here There This try tell see talk learn".split()
)
CHAT_PARTICLES = set("呢 吧 啊 嘛 呀 啦 吗 哦 呵呵 嘿嘿 哎 咦 欸 啥".split())
FORMAL_ENDINGS = ("ed", "ly", "ing")


def is_emoji(ch):
    return ord(ch) >= 0x1F300


def is_context_start(prefix):
    if len(prefix.token_ids) == 1:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def score(text):
    body = text.lstrip(" ")
    if text.strip() == "":
        return -0.7
    if "?" in text or "!" in text or any(is_emoji(c) for c in text):
        return -7.0
    if body in CHAT_PARTICLES:
        return -7.0
    if body.split(" ")[0] in CHAT_OPENERS:
        return -6.3
    if body[:1] and not body[:1].isalnum():
        return -3.0
    if body.isalpha() and body.endswith(FORMAL_ENDINGS):
        return 0.0
    if any("一" <= c <= "鿿" for c in text):
        return -2.4
    return -1.1


READS = ()


def step(carry, prefix, upstream):
    if not is_context_start(prefix):
        return None, 0.0
    return None, float(score(prefix.token_strings[-1]))

