"""A partial lexical/constructional approximation, leaving other tokens at zero.

Hiding/neighbor stems and reciprocal Chinese expressions give negative values.
Chinese negation/restriction and demonstratives give small positive values,
with larger boosts before dictionary-defined states/modals and localizers. We also recognize Chinese "this/that + not",
Vietnamese negative/restricted "have", and a document-opening Title: colon.
Token boundaries matter: isolated stems and compounds have different strengths.
"""
import re
from functools import lru_cache
import cedict
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
RELATION = re.compile(
    r'each other|one another|mutual|to (meet|intersect|accompany|connect|adjoin)'
    r'|acquaint|apart from|appointment'
)
STATE = re.compile(
    r'possible|to (want|desire|think|believe|have|need|love|fear|give)'
    r'|to be able|can;|capable|to seem|to resemble|to dare|willing'
)

@lru_cache(None)
def gloss(s):
    return '; '.join(cedict.glosses(s)).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', 0, ())
    _, previous_bytes, previous, position, history = carry
    s, b = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = 0.0
    if HAN.search(s):
        if s in ('邻', '鄰', '隣'):
            value -= 2.1
            if s == '鄰':
                value -= 1.55
        elif any(c in s for c in '邻鄰隣'):
            value -= 2.0
        if s in ('隐', '隱', '隠'):
            value -= 2.5
        elif any(c in s for c in '隐隱隠'):
            value -= 0.45
        reciprocal = s.startswith(('相', '互')) and len(s) > 1
        relation = bool(RELATION.search(gloss(s)))
        state = (bool(STATE.search(gloss(s)))
                 or s.startswith(('有', '给', '給')))
        if s in ('相', '互'):
            value -= 0.2
        if reciprocal:
            value -= 0.06
        if relation and (reciprocal or '彼此' in s):
            value -= 0.85
        if previous.endswith('相'):
            value -= 0.1
            if RELATION.search(gloss('相' + s)):
                value -= 1.14
        if previous.endswith(('不', '未', '无', '無', '没', '沒')):
            value += 0.13 + 0.32 * state
        if previous.endswith(('这', '這', '那', '哪')):
            value += 0.05
            if s[:1] in '里裡裏边邊儿兒间間面头頭':
                value += 0.82
        if previous.endswith(('这', '這', '那')) and s == '不':
            value = 2.25
        if previous.endswith(('只', '仅', '僅')):
            value += 0.03 + 0.35 * state
        if '任何' in s:
            value -= 0.33
            if s.startswith('有任何') or (
                s == '任何' and any(c in ''.join(history) for c in '不没沒无無有')
            ):
                value -= 1.2
        if '不可能' in s:
            value += 0.82
    # Vietnamese existential 'have', with negation or 'only'.
    if s.strip() == 'có' and previous.strip() in ('không', 'chưa', 'chỉ'):
        value = 1.0
    # Byte-split Japanese forms of the hiding/neighbor characters.
    if b == b'\xe9\x9a':
        value -= 1.1
    if '\ufffd' in s:
        completed = (previous_bytes[-2:] + b).decode('utf8', errors='ignore')
        if any(c in completed for c in '隐隱隠邻鄰隣'):
            value -= 1.8
    if s == ':' and previous == 'Title' and position == 1:
        value = 4.49
    return (doc, b, s, position + 1, (*history[-3:], s)), float(value)

"""A pulse at the start of a document (and its repeated opening token).

The pulse is larger for bare Latin/code tokens and smaller for connected
function words, East Asian writing, and sentence punctuation. After the
initial identical-token run, predict zero. These are coarse class means,
not a reconstruction of the substantial token-specific variation.
"""
import unicodedata

READS = ()
CONJUNCTIONS = set(
    'and or but nor yet so because although though while if unless whether as'.split()
)
DEMONSTRATIVES = set('this that these those which'.split())
PRONOUNS = set('i me you he him she her it we us they them who whom'.split())
MODALS = set('can could may might must shall should will would'.split())
AUXILIARIES = set(
    'be am is are was were been being have has had do does did'.split()
)
ARTICLES = {'a', 'an', 'the'}
C_ESCAPES = set('nrtabfv') | {"'", '"'}


def opening_strength(s):
    word = s.strip()
    if s.startswith('<|'):
        return 15.5 if s == '<|endoftext|>' else 2.6
    if not word:
        if '\r\n' in s:
            return 12.0
        if '\n' in s:
            return 4.5 if s.count('\n') > 1 else 7.0
        if '\t' in s:
            return 7.3 if s == '\t' else 3.7
        return 1.8 if s == ' ' else 3.4
    if word.isdecimal():
        return 6.7
    if s.startswith('\\'):
        if len(s) == 2 and s[1] in C_ESCAPES:
            return 27.0
        return 9.0 if len(s) <= 2 else 14.0
    if word.startswith('#!'):
        return 15.5
    if word.startswith('#') and any(c.isalpha() for c in word):
        return 12.0
    if not any(c.isalnum() for c in word):
        if len(word) > 1 and len(set(word)) == 1:
            return 6.2 if word[0] == '#' else 9.0
        if word[0] in ',，、:':
            if s.count('\n') == 1:
                return 6.0
            return 1.6 if len(word) == 1 else 6.0
        if word[0] in '.。':
            if s.count('\n') == 1:
                return 5.5
            return 2.3 if len(word) == 1 else 6.0
        if word[0] in ')]}':
            return 3.0 if len(word) == 1 else 4.5
        if word[0] in '([{':
            return 5.0 if len(word) == 1 else 8.5
        if word[0] in "\"'`“”‘’":
            return 6.0
        return 4.8
    name = unicodedata.name(word[0], '')
    if 'CJK' in name:
        return 2.8
    if 'HIRAGANA' in name:
        return 1.6
    if 'HANGUL' in name:
        return 3.5
    if not word.isascii():
        return 4.5
    if not word.isalpha():
        return 9.5
    bare = not s.startswith(' ')
    if word.isupper() and len(word) > 1:
        return 9.8 if bare else 6.5
    lower = word.lower()
    if lower in CONJUNCTIONS:
        return 3.4 if bare else 1.7
    if lower in DEMONSTRATIVES:
        return 2.5
    if lower in PRONOUNS:
        return 4.8 if bare else 3.0
    if lower in MODALS:
        return 2.6
    if lower in AUXILIARIES:
        return 3.5
    if lower in ARTICLES:
        return 5.5 if bare else 4.8
    if not bare:
        return 5.1 if word[0].isupper() else 4.1
    if word[0].isupper():
        return 7.8 if len(word) <= 3 else 6.8
    return 6.1 if len(word) <= 3 else 5.4


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    token = prefix.token_ids[-1]
    if first:
        value = opening_strength(prefix.token_strings[-1])
        return (token, True, value), value
    opening_token, still_repeating, value = carry
    still_repeating = still_repeating and token == opening_token
    prediction = value if still_repeating else 0.0
    return (opening_token, still_repeating, value), prediction

"""Approximate a sparse, cross-token word-fragment response.

Short word-initial s/sh/st/th fragments sometimes elicit negative responses on
an adjoining short continuation. Common completed words are downweighted using
word frequency. A few recognizable rimes reverse the sign. Greek consonant
clusters and Japanese loanword syllables have separate spelling-based rules.
This is a coarse approximation, not a predictor of every lexical exception.
Small additional rules cover initial capital consonants and punctuation runs.
Many lexical exceptions, including Thai and Chinese responses, are not modeled.
"""
import codecs
import unicodedata
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=16000)
def roman(s):
    return anyascii(s).lower()

@lru_cache(maxsize=16000)
def fragment_response(p, s):
    """Short consonant onsets followed without an intervening word boundary."""
    p = p.strip().strip('.,-_/\\(\"\'[{')
    if not p.isalpha() or not s.isalpha():
        return 0.
    a, b = roman(p), roman(s)
    if not b or len(b) > 5:
        return 0.
    if a in {'sh', 'she', 'sch', 'shr', 'shw'}:
        family = 'sh'
    elif a in {'st', 'ste', 'str', 'sth', 'sz', 'szcz'}:
        family = 'st'
    elif a in {'th', 'tw', 'tr'}:
        family = 'th'
    elif a == 's' or regex.fullmatch(r's[bcdfghjklmnpqrstvwxyz]{1,2}', a):
        family = 's'
    else:
        return 0.
    # Positive nasal/velar rimes contrast with most other continuations.
    if b == 'un':
        return {'sh': 2.3, 'st': 1.4, 'th': 3.6, 's': .2}[family]
    if b == 'ri' and family == 'sh':
        return -2.2
    if b == 'ap' and family == 'sh':
        return -5.3
    if b in {'on', 'ok', 'ink'}:
        return .7 if family in {'sh', 'st'} else .15
    if b.startswith('r'):
        value = -.65
    elif len(b) == 1 and b in 'aeiouy':
        value = -.45
    else:
        value = -.25
    value *= {'sh': 1., 'st': 1., 'th': .35, 's': .2}[family]
    language = 'en'
    if regex.search(r'\p{Script=Cyrillic}', p + s):
        language = 'ru'
    elif regex.search(r'\p{Script=Arabic}', p + s):
        language = 'ar'
    frequency = zipf_frequency(p + s, language)
    return value * min(1., max(0., (4.5 - frequency) / 2.))


def greek_response(word, s):
    if not regex.fullmatch(r'\p{Script=Greek}+', s):
        return None
    r = ''.join(c for c in unicodedata.normalize('NFD', s)
                if not unicodedata.combining(c)).lower()
