        if r == 'ι':
            return -6.3 if len(word) == 2 else -3.3
        if r in {'ε', 'ρ'}:
            return -.9
        if r in {'α', 'ο', 'ω', 'ου'}:
            return -.3
        return 0.
    if word in {'σ', 'Σ'}:
        if r == 'π':
            return -3.1
        if r == 'χ':
            return -1.2
        return -.7 if r in {'α', 'ε', 'η', 'ω'} else 0.
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        decoder = codecs.getincrementaldecoder('utf8')('replace')
        p, pstart, word, position = '', True, '', 0
        repeated, initial = True, prefix.token_bytes[-1]
    else:
        _, decoder, p, pstart, word, position, repeated, initial = carry
        position += 1
        repeated = repeated and prefix.token_bytes[-1] == initial
    s = decoder.decode(prefix.token_bytes[-1])
    starts = first or not s or not s[0].isalpha() or not p or not p[-1].isalpha()
    value = fragment_response(p, s) if pstart else 0.
    greek = greek_response(word, s)
    if greek is not None:
        value = greek
