    if p.strip() in {'ス', 'スト', 'サ', 'シェ', 'シュ', 'グ'}:
        if regex.fullmatch(r'\p{Script=Katakana}+', s):
            r = roman(s)
            if r in {'ri', 'kuri', 'puri'}:
                if p.strip() in {'ス', 'スト'}:
                    value = -3.5
                else:
                    value = -1.3 if p.strip() == 'グ' else -.3
            elif len(r) == 2 and r[0] in 'tkn' and r[1] in 'aoe':
                value = -2. if p.strip() in {'ス', 'スト', 'シェ'} else -.5
            elif len(r) <= 5:
                value = -.3
    if position == 1 and p.lower() == 'title' and s == ':':
        value = -3.42
    if repeated:
        if s and not s.strip('·'):
            value = -1.2
        elif s == '\r':
            value = 4.38
        elif s in {'\\n', '\\t'}:
            value = -1.45
        elif len(s) == 1 and s.isascii() and s.isupper() and s not in 'AEIOU':
            value = .55
    trailing = regex.search(r'\p{L}+$', word + s)
    word = trailing[0][-20:] if trailing else ''
    return (doc, decoder, s, starts, word, position, repeated, initial), value

