"""Layer-1 MLP down_proj component 3511: a detector for letters that complete a
vowel spelling in a non-Latin script, when that letter is split across tokens.

It goes strongly negative on:
  * Greek "ει"/"εί": the token ι or ί right after a token ending in ε or έ
    (e.g. "ασφάλε|ια", "μειώσε|ι").                              about -6.5
  * Korean "게이"/"베이" style: the syllable 이 right after a syllable whose vowel
    is ㅔ (e.g. "게|이트").                                        about -6.3
  * a broken fragment of a Japanese long-vowel word: a token containing the
    katakana long-vowel mark ー together with a broken UTF-8 byte.  about -1.8
  * a lone broken byte (U+FFFD) right after a Thai letter.           about -1.5
Everywhere else it predicts 0. Values are typical means measured on training text.
"""

READS = ()

GREEK_GLIDE = {"ι", "ί"}
GREEK_E = {"ε", "έ"}
HANGUL_BASE, HANGUL_END = 0xAC00, 0xD7A3
HANGUL_E_MEDIAL = 5  # index of ㅔ in the Hangul medial vowel order
BROKEN = "�"


def _has_e_syllable(text):
    """True if the last character is a Hangul syllable whose vowel is ㅔ."""
    if not text:
        return False
    code = ord(text[-1])
    if not HANGUL_BASE <= code <= HANGUL_END:
        return False
    return (code - HANGUL_BASE) // 28 % 21 == HANGUL_E_MEDIAL


def _has_thai(text):
    return any("฀" <= ch <= "๿" for ch in text)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if prefix.position == 0:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    if cur in GREEK_GLIDE and prev[-1:] in GREEK_E:
        return carry, -6.5
    if cur == "이" and _has_e_syllable(prev):
        return carry, -6.3
    if "ー" in cur and BROKEN in cur:
        return carry, -1.8
    if cur == BROKEN and _has_thai(prev):
        return carry, -1.5
    return carry, 0.0

