        if word == 'only':
            value = 1.75 + (0.65 if previous.strip() == 'The' else 0.0)
        elif word == 'several':
            value = 3.5
        elif word in {'some', 'all', 'any', 'each', 'every', 'exactly'}:
            value = 1.8
        elif word in REFERENCE:
            value = 1.2 if word == 'specified' else 0.75
        elif word in {'identical', 'similar'}:
            value = 1.1
        elif word == 'same':
            value = -0.07
        elif word == 'above':
            value = -0.8 if before.strip().lower() == 'of' else -0.15
    elif prev in POSSESSIVE:
        if word == 'only':
            value = 1.35

    if prev == 'both':
        if word == 'of':
            value = 0.8 if previous.strip() == 'Both' else 1.6
        elif word in {'these', 'those'}:
            value = 2.5
    elif prev == 'all' and word in {'these', 'those'}:
        value = 0.25
    elif prev == 'some' and word == 'of':
        value = -0.28
    if word == 'another' and prev in {'and', 'or', 'is', 'just'}:
        value = 0.65
    if word == 'both':
        if prev in {'are', 'is', 'and', 'so', 'at', 'between'}:
            value = 0.75
        elif prev in {'multiply', 'divide'}:
            value = 1.5
    if word == 'every' and prev == 'and':
        value = 1.5 if before.strip().lower() == 'each' else 0.0
    if word == 'several':
        if prev == 'last':
            value = 4.5
        elif prev in {'after', 'into'}:
            value = 0.8

    if prev in {'big', 'large', 'most'} and word not in FUNCTION:
        value = {'big': -0.15, 'large': 0.0, 'most': -0.07}[prev]
        if prev in {'big', 'large'} and word == 'data':
            value = 1.3
        elif prev == 'big' and word == 'o':
            value = 5.5
