    if previous.endswith('小') and token == '型':
        value = 0.9
    if word == 'test' and previous.rstrip().endswith('@'):
        value = -1.15
    if len(token) > 1 and not token.strip('·'):
        value = -0.64
    if not previous and token == '##':
        value = -1.85
    return (doc, token, previous), value

"""Recognize result/consult words and the spelling 'sul', even across tokens.

The largest response is to a short token that completes 'sul'.  Integrated
words have smaller responses.  Result words also distinguish a consequence
verb from a noun or a code identifier, using a few preceding grammar words.
Weaker rules cover suit, consist, follow, suff-, and doubled middle dots.
Latin and Cyrillic spelling is transliterated; other scripts are ignored.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()
MODALS = frozenset('may might can could will would shall should must'.split())
DETERMINERS = frozenset(
    'the a an this that these those my your our their its'.split()
)


@lru_cache(maxsize=8192)
def romanize(text):
    # Only transliterate alphabetic scripts whose spelling has this syllable.
    text = ''.join(
        ch if not ch.isalpha() or any(
            script in unicodedata.name(ch, '') for script in ('LATIN', 'CYRILLIC')
        ) else ' ' for ch in text
    )
    return anyascii(text).lower().replace("'", '')


def activation(tail, text):
    s = romanize(text)
    previous = re.findall('[a-z]+', tail)
    prev = previous[-1] if previous else ''
    old = re.search('[a-z]*$', tail).group()
    leading = re.match('[a-z]+', s)
    if leading and old:
        new = leading.group()
        word = old + new
        k = word.find('sul')
        # Capsule/encapsulate is a quiet spelling exception.
        if 'capsul' in word:
            return 0.0
        if k >= 0 and k < len(old) < k + 3:
            if len(new) > 3:
                return 3.0
            return 9.3 if word.endswith('sult') else 5.8
        if k >= 0 and k + 3 <= len(old):
            if old.endswith('sul') and new == 'ter':
                return 7.6
            if old.endswith('sult') and new in {'ing', 'ed', 's'}:
                return 4.5
            if old.endswith('sul') and new.startswith(('ph', 'f', 'z')):
                return 2.6
            return 0.2
    words = re.findall('[a-z]+', s)
    word = words[0] if words else ''
    if len(text) >= 2 and set(text) == {'·'}:
        return -1.4
    # Consequence verbs are stronger than nouns and code identifiers.
    if word.startswith('result'):
        ending = word[6:]
        if ending == 'ed':
            return 3.8
        if ending == 'ing':
            return 1.9 if prev in DETERMINERS else 5.0
        if ending == 's' and prev in {'it', 'which', 'that', 'this'}:
            return 4.1
        if not ending and (prev in MODALS or prev in {'to', 'not'}):
            return 6.2
        if text.startswith(' ') and text.lstrip().startswith('result'):
            return 1.2
        return 1.0
    # Related lexical families, with weaker extended consulting nouns.
    if word.startswith('consul'):
        if not word.startswith('consult'):
            return 6.4
        if 'ation' in word or 'ancy' in word:
            return 2.3
        if 'ant' in word:
            return 3.7
        return 4.8
    if 'insult' in word:
        return 3.3
    if 'sul' in word:
        if word.endswith('sult') and len(word) <= 6:
            return 3.0
        if word.startswith('sul') and (len(word) <= 4 or word == 'sulph'):
            return 3.5
        return 0.2
    if word in {'suit', 'suits', 'suitable'}:
        if 'abl' in word:
            return 2.1
        return 2.3 if prev == 'to' else 1.6
    if word in {'consist', 'consists', 'consisted', 'consisting'}:
        return 1.9
    if word in {'follow', 'follows', 'followed'}:
        if prev == 'as':
            return 0.1
        if prev in {'it', 'will', 'would', 'not', 'necessarily'}:
            return 2.7
        return 0.8
    if word in {'suff', 'suffice'}:
        return 1.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    value = activation(tail, text)
    tail = (tail + romanize(text))[-80:]
    return (doc, tail), value

"""Sparse lexical cues, not one unified semantic category.

Positive cues are split -ur-/-um endings, especially after t-ending stems,
and meeting/discussion or examination words. Parsing errors, a Chinese
question-and-answer label, and repeated middle dots are negative. Two code
openers have document-initial responses. Longer-context variation and most
weak lexical responses are omitted; the suffix rules are broad averages.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if first else prefix.token_strings[-2]
    # Recover a preceding character split across byte-level tokens.
    if ('\ufffd' in previous and prefix.position >= 2 and
            prefix.document_ids[-3] == prefix.document_ids[-1]):
        previous = b''.join(prefix.token_bytes[-3:-1]).decode(
            'utf-8', errors='ignore')
    stem = previous.lower().rstrip()
    ending = token.lower()
    value = 0.0

    if ending in ('ure', 'ures', 'ured', 'uring', 'ur', 'ural'):
        value = -0.08
        if stem.endswith('t'):
            value = 1.1 if stem.endswith('ct') else 0.25
        if stem.endswith('nt') and ending in ('ure', 'ured'):
            value = 4.2
        elif stem.endswith('nct'):
            value = 3.2
        elif ending == 'ural':
            value = 1.2 if stem.endswith('x') else 0.0
    elif ending == 'um':
        if stem.endswith(('lt', 'ct')):
            value = 2.1
        elif stem.endswith('tr'):
            value = 1.5
        elif stem.endswith('t'):
            value = 0.7
    elif word == '議':
        value = 1.9 if stem.endswith('思') else 3.8
    elif word == '议':
        value = 0.8 if stem.endswith('建') else 2.7
    elif word in ('议论', '議論'):
        value = 3.2
    elif word in ('会议', '會議'):
        value = 2.0
    elif word in ('会议上', '會議上'):
        value = 1.4
    elif word in ('协议', '協議'):
        value = 1.9
    elif word in ('建议', '建議', '审议', '審議'):
        value = 0.65
    elif word.lower() == 'meeting':
        value = 0.5
    elif word in ('考试', '考試'):
        value = 1.5
    elif word in ('问答', '問答'):
        value = -1.9
    elif word.lower() == 'error' and stem.strip() in ('syntax', 'parse'):
        value = -0.95
    elif len(word) >= 2 and set(word) == {'·'}:
        value = -1.1
    elif first and token == '//\n':
        value = 2.21
    elif first and token == 'package':
        value = 0.96
    return None, value

"""Estimate recurring local syntax transitions.

Dashed table joints and Git diff options are positive; ISO timestamp separators,
selected hash/percent markers, and web-feed boundaries are negative. These rules
approximate large training activations, not a general topic or syntax classifier.
Small offsets handle document/conversation boundaries. Weaker lexical effects
are left at zero. The state is just the previous token and 100 text characters.
"""
import re

READS = ()


def score(token, prev, tail, start):
    s = token.strip()
    if start:
        if s.isascii() and s.isalpha():
            if token.startswith(' '):
                return 0.11
            if len(s) == 1:
                return 0.47 if s.isupper() else 0.15
            return 0.21 if s[0].isupper() else 0.32
        return 0.22 if s.isdecimal() else 0.14

    if token == 'T' and re.search(r'\d{4}-\d{2}-\d{2}$', tail):
        # Run-on numeric metadata strengthens the date/time boundary.
        crowded = re.search(r'\d{5,}-\d{2}-\d{2}$', tail)
        return -14.0 if crowded else -8.5
    if token == 'Z' and re.search(r'\d:\d\d(?:\.\d+)?$', tail):
        return -3.4
    if s in ('UTC', 'GMT') and re.search(r'\d[:\d.\s+()-]*$', tail):
        return -1.6

    # Horizontal strokes ending at a table intersection.
    rule = re.search(r'[-+]+:?$', tail)
    if rule and s in ('|', '+'):
        strokes = rule[0]
        if '-' in strokes:
            if '+' in strokes:
                return 6.4
            if strokes.endswith(':'):
                return 3.2
            if len(strokes) < 3:
                return 1.8
            if token.startswith(' '):
                return 3.1
            if token.endswith('\n'):
                return 2.0
            return 10.0 if s == '+' else 7.4
    if prev.strip() == '--':
        if token == 'git':
            return 5.3
        if token == 'short':
            return 2.0
        if s and set(s) == {'='}:
            return -3.9
        if token[0:1].isalpha():
            return 0.1

    if prev.endswith('#') and not token.startswith(' '):
        # Conventional table/figure, source-line, and section anchors.
        if token == 'L':
            return -8.5
        if token == 't':
            return -4.5
        if token in ('F', 'f', 'C', 'S', 's', 'table'):
            return -1.4
        if token == 'fig':
            return -0.7
    if prev.endswith('%'):
        if token == 'T':
            return -4.4
        if token in ('q', 'Y'):
            return -0.9
        if token == '_':
            return -1.6

    if s in '┌┐└┘├┤┬┴┼' and len(s) == 1:
        if prev.endswith(('─', '━')):
            return 5.5

    # URL roles: Git references, and Blogger's feed metadata.
    if token == '/master':
        return 4.8
    if token in ('/blob', '/tree'):
        return 1.6
    if token == '.com' and tail.endswith('blogger'):
        website = re.search(r'https?://(?:www\.)?blogger$', tail)
        return -4.2 if website else -8.0
    if token == '/profile' and tail.endswith('blogger.com'):
        return -7.4
    if token == '.post' and prev.isdecimal() and 'blog-' in tail:
        return -8.9
    if token == '.php' and re.search(r'https?://\S*$', tail):
        return -1.8
    if token == '<think>':
        return -0.23
    if token == '</tool_response>':
        return -0.145
    if token == '<|im_end|>':
        return -0.04
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    prev, tail = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    value = score(token, prev, tail, start)
    return (doc, token, (tail + token)[-100:]), value

"""Approximate two sparse responses: code wildcards and Chinese change words.

Large negatives mark wildcard imports, grouped namespaces and regex/glob
patterns, rather than ordinary comment or multiplication stars.  Smaller
branches cover private attributes and SQL wildcards.  Chinese quantity-change
and action/state words are positive; entering and identity comparisons are
negative.  Compounds can finish in a separate token.  Unmatched tokens get zero.
A bounded byte tail preserves split characters and resets between documents;
literal backslash-n is treated as a line break in quoted code too.
"""
import re
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')


def activation(token, before):
    s = token.strip()
    joined = before[-1:] + token
    imported = re.search(r'\b(?:import|from)\s+(?:static\s+)?[\w.$]*$', before)
    pattern = re.search(r'grep|match|regex|pattern|replace|re\.|-run\b|:%s/',
                        before, re.I)
    if '*' in token:
        if '::*' in before[-2:] + token:
            return -5.3
        if re.search(r'\bimport\s*$', before) and s.startswith('*'):
            return -6.5 if re.search(r'\bfrom\b.*\bimport\s*$', before) else -4.0
        if re.search(r'\.\*(?!\*)', joined):
            if imported:
                return -11.5
            if s.startswith('?='):  # a lookahead, not a new capture
                return -1.0
            if before.endswith('\\'):
                return -2.5
            if pattern or before.endswith('(') or re.search(r'\bselect\b', before, re.I):
                return -4.8
            return -1.5
        if '*.' in token:
            return -1.4
        if re.search(r'\bselect\s*$', before, re.I):
            return -1.5
    if '::{' in before[-2:] + token:
        return -3.5
    if '.+' in joined:
        return -5.0 if pattern or before.endswith(('(', '(.')) else -1.5
    if '.{' in joined:
        return -6.0 if re.search(r'\*/?\.\{', before[-8:] + token) else -2.2
    if '._' in joined and '.__' not in joined:
        if imported:
            return -4.0
        return 0.1 if before.endswith('self') else -0.65
    if s == 're' and re.search(r'\bimport\s*$', before):
        return -2.5
    if s in {'await', 'into'} and before.endswith('.'):
        return -1.7
    if len(s) >= 2 and set(s) == {'·'}:
        return 0.76

    if any(ord(ch) > 127 for ch in s):
        s = SIMPLIFY.convert(s)
        if s.endswith(('了', '的')):
            s = s[:-1]
    previous = SIMPLIFY.convert(before[-1:]) if s in {'少', '造'} else ''
    if s == '减少' or (s == '少' and previous == '减'):
        return 2.8
    if s == '少':  # few / less
        return 1.7
    if s == '增加':
        return 1.6
    if s == '加' and before.endswith(('增', '増')):
        return 2.8
    if s == '加' and before.endswith('追'):
        return 1.1
    if s == '造' and previous == '制':  # manufacture
        return 2.4
    if s == '造' and previous in {'缔', '筑'}:
        return 1.1
    if s in {'提高', '降低', '创造', '制造', '积累', '带来', '分享',
             '处于', '改变', '变得', '避免'}:
        return 0.8
    if s == '进行':  # carry out
        return 0.7
    if s == '进入':  # enter
        return -0.8
    if s in {'同一', '同一个', '相同', '不一样'}:
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = carry[1] if carry is not None and carry[0] == doc else b''
    value = activation(prefix.token_strings[-1], raw.decode('utf-8', 'replace'))
    raw = (raw + prefix.token_bytes[-1]).replace(b'\\n', b'\n')
    raw = raw[-480:].rsplit(b'\n', 1)[-1]
    return (doc, raw), value

"""A document-initial token response, sustained through an identical-token run.

Formatting markers are usually strongly positive; ordinary words have a smaller
response depending on case, frequency and grammatical class. After the opening
run changes token, predict zero. These are coarse training-derived averages,
not an exact lexical model of the component.
"""
from functools import lru_cache
import unicodedata
import regex
from wordfreq import zipf_frequency
import wordnet

READS = ()
PRONOUNS = set('i you he she it we they me him her us them'.split())
IMPORTS = set('import require include'.split())
DECLARATIONS = set(
    'class const function def public private static let var package '
    'typedef enum struct template void int'.split()
)
QUESTIONS = set('who whom whose which what where when why how'.split())


def only(s, characters):
    return bool(s) and all(c in characters for c in s)


@lru_cache(maxsize=8192)
def opening_value(text):
    s = text.strip()
    low = s.lower()
    newline = '\n' in text or '\r' in text
    if text.startswith('<|'):
        return 9.1 if text == '<|endoftext|>' else 0.0
    if not s:
        if only(text, '\r'):
            return -0.75
        return 3.6 if newline else 4.9
    if only(s, '#'):
        return 14.34 if len(s) == 1 else 11.8
    if s.isdigit():
        return 5.08 if s == '0' else 1.69 if s == '1' else 2.7
    if only(s, '·•●'):
        return 6.5
    if all(unicodedata.category(c)[0] in 'PS' for c in s):
        if only(s, '.…'):
            return 2.6 if newline else 5.9
        if only(s, ',，'):
            return 1.64
        if only(s, '([{<【'):
            return 4.7
        if only(s, '/\\*'):
            return -0.45 if s == '//' and newline else 7.0
        if only(s, '|'):
            return 6.1
        if only(s, '-–—'):
            return 5.5
        if only(s, '_'):
            return 6.9
        if only(s, '\'"‘’“”`'):
            return 3.5
        return 2.6
    if '\ufffd' in s:
        return -1.4
    latin = bool(regex.search(r'\p{Script=Latin}', s))
    if not s.isalpha():
        return -1.3 if latin else 2.6
    frequency = zipf_frequency(low, 'en') if s.isascii() else 0.0
    if low == 'the':
        return (3.42 if text.startswith(' ') else 5.82) if s.istitle() else 1.69
    if low in PRONOUNS:
        return -0.6 if len(s) == 1 else -3.2
    if low in ('a', 'an'):
        return 3.4 if s.istitle() else -0.1
    if low in ('of', 'in', 'to'):
        return 4.0 if s.istitle() else 2.5
    if s.islower():
        if low in IMPORTS:
            return 10.8
        if low in DECLARATIONS:
            return 6.1 if len(s) <= 6 else 3.3
        if text.startswith(' '):
            return -1.5 if frequency < 4 else -0.65
        if len(s) <= 3:
            return -0.93
        return 1.38 if 'noun' in wordnet.parts_of_speech(low) else 0.16
    if not s.istitle():
        return 0.7
    if not latin:
        return 0.2
    if len(s) <= 3:
        if frequency < 2.7:
            return -4.9
        if frequency < 4.3:
            return -2.17
        return -0.38 if frequency < 5.6 else 2.09
    if frequency < 3.4:
        return -1.0
    if low in QUESTIONS:
        return 5.5
    return -1.0 if frequency >= 6.5 else 2.15


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = opening_value(prefix.token_strings[-1])
        return (document, token, value, True), value
    document, first_token, value, uniform = carry
    uniform = uniform and token == first_token
    return (document, first_token, value, uniform), value if uniform else 0.0
